-- Vorrats-Aufgaben (rollend-6) in bestehende Flüge einfügen: 198 Aufgaben, 8 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (9, 'bruch.brueche', 861, 42, $auf$[{"l": "bruchteil_von", "t": "bruchteil_von", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 3/8 von 56 kg. Zuerst teilst du durch den Nenner: Ein Achtel sind ① kg. Dann nimmst du so viele Teile, wie der Zähler sagt: 3/8 sind ② kg. Der Rest der 56 kg wiegt ③ kg.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 21, 35]}, "h": "Der Nenner sagt, in wie viele gleiche Teile du das Ganze teilst.", "w": "56 kg : 8 = 7 kg ist ein Achtel. Drei Achtel sind 3 · 7 kg = 21 kg. Der Rest ist 56 kg − 21 kg = 35 kg.", "form": "lueckenweg", "zaehlt": "nein", "r": 6862}, {"l": "bruchteil_von", "t": "bruchteil_von", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Von einer 72 m langen Schnur wird ein Stück abgeschnitten. Es ist ?/8 der Schnur und 45 m lang. Welche Zahl steht an der Stelle des Fragezeichens?"}, "o": {"wert": 5}, "h": "Wie lang ist ein Achtel der ganzen Schnur?", "w": "Ein Achtel der Schnur sind 72 m : 8 = 9 m. Das Stück hat 45 m. 45 m : 9 m = 5. Probe: 5/8 von 72 m = 45 m.", "form": "umkehren", "zaehlt": "ja", "r": 6863}, {"l": "bruchteil_von", "t": "bruchteil_von", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Wanderweg ist 24 km lang. Am ersten Tag geht die Gruppe 3/8 des ganzen Weges, am zweiten Tag 1/4 des ganzen Weges. Wie viele Kilometer bleiben für den dritten Tag?"}, "o": {"wert": 9, "einheit": "km"}, "h": "Rechne beide Tagesstrecken aus. Was bleibt vom ganzen Weg übrig?", "w": "Erster Tag: 24 km : 8 · 3 = 9 km. Zweiter Tag: 24 km : 4 = 6 km. Rest: 24 km − 9 km − 6 km = 9 km.", "form": "anwenden", "zaehlt": "ja", "r": 6864}, {"l": "anteil_bestimmen", "t": "anteil_bestimmen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In einer Gruppe sind 36 Kinder, 15 davon spielen Fußball. Der Anteil ist 15/36. Kürze mit dem größten gemeinsamen Teiler ①. Der gekürzte Anteil ist dann ②/③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 5, 12]}, "h": "Suche die größte Zahl, die in 15 und in 36 steckt.", "w": "Der größte gemeinsame Teiler von 15 und 36 ist 3. 15 : 3 = 5 und 36 : 3 = 12. Der Anteil ist 5/12.", "form": "lueckenweg", "zaehlt": "nein", "r": 6865}, {"l": "anteil_bestimmen", "t": "anteil_bestimmen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "In einer Klasse sind 28 Kinder, 21 davon kommen mit dem Rad. Weg A: Kürze 21/28 direkt. Weg B: Berechne und kürze den Anteil der 7 Kinder ohne Rad und ziehe ihn von 1 ab. Beide Wege müssen denselben Anteil ergeben. Welcher Anteil der Kinder kommt mit dem Rad? Schreibe ihn als vollständig gekürzten Bruch.", "schablone": "□/□", "hinweis": "Zähler ins erste Kästchen, Nenner ins zweite. Vollständig gekürzt."}, "o": {"werte": [3, 4]}, "h": "Prüfe, ob beide Wege am Ende dasselbe ergeben.", "w": "Weg A: 21/28 = 3/4 (durch 7 gekürzt). Weg B: 7/28 = 1/4, dann 1 − 1/4 = 3/4. Beide Wege führen zu 3/4.", "form": "zwei_wege", "zaehlt": "ja", "r": 6866}, {"l": "anteil_bestimmen", "t": "anteil_bestimmen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Mia bestimmt, welcher Anteil der 45 Schüler in der AG ist. 18 Schüler sind in der AG. Zeile 1: Anteil = Ganzes : Teil = 45/18 Zeile 2: 45/18 = 5/2 (durch 9 gekürzt) Zeile 3: 45/18 = 2 1/2 In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Was kommt in den Zähler, was in den Nenner?", "w": "Der Teil (18) kommt in den Zähler, das Ganze (45) in den Nenner: 18/45 = 2/5. Zeile 1 hat Teil und Ganzes vertauscht; die späteren Zeilen rechnen damit richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6867}, {"l": "ganzes_bestimmen", "t": "ganzes_bestimmen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "3/5 einer Strecke sind 27 km lang. Zuerst bestimmst du, wie lang ein Fünftel ist: ① km. Dann bekommst du die ganze Strecke: ② km. Ohne diese 27 km ist die Strecke noch ③ km lang.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, 45, 18]}, "h": "Teile zuerst durch den Zähler, um ein Teil zu erhalten.", "w": "27 km : 3 = 9 km ist ein Fünftel. Das Ganze sind 5 Fünftel: 5 · 9 km = 45 km. Ohne die 27 km bleiben 45 km − 27 km = 18 km.", "form": "lueckenweg", "zaehlt": "nein", "r": 6868}, {"l": "ganzes_bestimmen", "t": "ganzes_bestimmen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Händler verkauft am Montag 2/5 seiner Äpfel. Das sind 18 kg. Wie viele Kilogramm Äpfel hatte er vorher?"}, "o": {"wert": 45, "einheit": "kg"}, "h": "Wie viel kg sind ein Fünftel?", "w": "18 kg : 2 = 9 kg ist ein Fünftel. Alle 5 Fünftel: 5 · 9 kg = 45 kg.", "form": "anwenden", "zaehlt": "ja", "r": 6869}, {"l": "ganzes_bestimmen", "t": "ganzes_bestimmen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Behälter ist zu 3/8 gefüllt. Man gießt 12 l hinzu. Jetzt ist er zu 3/4 gefüllt. Wie viele Liter passen in den ganzen Behälter?"}, "o": {"wert": 32, "einheit": "l"}, "h": "Welcher Bruchteil des Behälters sind die 12 l?", "w": "Hinzugekommen sind 3/4 − 3/8 = 3/8 des Behälters. 3/8 sind 12 l, also 1/8 = 4 l und 8/8 = 32 l.", "form": "umkehren", "zaehlt": "ja", "r": 6870}, {"l": "erweitern", "t": "erweitern", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Erweitere 3/8 auf den Nenner 56. Wie oft passt der alte Nenner in den neuen? Die Erweiterungszahl ist ①. Der neue Zähler ist ②. Bis zum Ganzen fehlen dem Bruch dann ③ Sechsundfünfzigstel.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 21, 35]}, "h": "Mit welcher Zahl wird aus dem Nenner 8 der Nenner 56?", "w": "56 : 8 = 7. Zähler und Nenner werden mit 7 malgenommen: 3 · 7 = 21. Also 3/8 = 21/56. Das Ganze sind 56/56, es fehlen 56 − 21 = 35 Sechsundfünfzigstel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6871}, {"l": "erweitern", "t": "erweitern", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Der Bruch 6/7 wurde erweitert. Es entstand 48/56. Mit welcher Zahl wurde erweitert?"}, "o": {"wert": 8}, "h": "Wie oft passt der alte Zähler in den neuen?", "w": "48 : 6 = 8 und 56 : 7 = 8. Es wurde mit 8 erweitert.", "form": "umkehren", "zaehlt": "ja", "r": 6872}, {"l": "erweitern", "t": "erweitern", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Pizza ist in 8 gleiche Stücke geschnitten. Tim isst 3 Stücke. Eine zweite, gleich große Pizza ist in 24 gleiche Stücke geschnitten. Wie viele von diesen kleinen Stücken muss Ben essen, um genauso viel Pizza zu essen wie Tim?"}, "o": {"wert": 9}, "h": "Wie viele kleine Stücke ergeben ein großes Stück?", "w": "Ein großes Stück sind 24 : 8 = 3 kleine. Tim isst 3 große Stücke, das sind 3 · 3 = 9 kleine. 3/8 = 9/24.", "form": "anwenden", "zaehlt": "ja", "r": 6873}, {"l": "ggt", "t": "ggt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bestimme den ggT von 48 und 180 mit dem Teilen mit Rest. 180 geteilt durch 48 lässt den Rest ①. Dann teilst du 48 durch ①; der Rest ist ②. Dieser Rest teilt ① ohne Rest und ist der ggT. Kürzt du 48/180 damit, ist der neue Nenner ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [36, 12, 15]}, "h": "Teile mit Rest: Welcher Rest bleibt, wenn du die größere Zahl durch die kleinere teilst?", "w": "180 : 48 = 3 Rest 36. 48 : 36 = 1 Rest 12. 36 : 12 geht ohne Rest, also ist der ggT 12. 180 : 12 = 15, der neue Nenner ist 15 (48/180 = 4/15).", "form": "lueckenweg", "zaehlt": "nein", "r": 6874}, {"l": "ggt", "t": "ggt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Fläche von 24 cm mal 36 cm soll ohne Lücken mit gleich großen Quadraten ausgelegt werden. Die Quadrate sollen so groß wie möglich sein. Wie lang ist die Seite eines Quadrats in Zentimetern?"}, "o": {"wert": 12, "einheit": "cm"}, "h": "Die Seitenlänge muss in 24 und in 36 ohne Rest passen.", "w": "Gesucht ist der größte gemeinsame Teiler von 24 und 36. 24 = 2 · 2 · 2 · 3 und 36 = 2 · 2 · 3 · 3. Gemeinsam: 2 · 2 · 3 = 12. Das Quadrat hat 12 cm Seitenlänge.", "form": "anwenden", "zaehlt": "ja", "r": 6875}, {"l": "ggt", "t": "ggt", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Jan bestimmt den größten gemeinsamen Teiler von 36 und 60. Zeile 1: Teiler von 36: 1, 2, 3, 4, 6, 9, 12, 18, 36 Zeile 2: Teiler von 60: 1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60 Zeile 3: Gemeinsame Teiler: 1, 2, 3, 4, 6, 12 Zeile 4: Der ggT ist der kleinste gemeinsame Teiler, also 1 In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Was heißt „größter“ gemeinsamer Teiler?", "w": "Die Zeilen 1 bis 3 stimmen. In Zeile 4 wurde der kleinste statt der größte gemeinsame Teiler genommen: richtig ist 12.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6876}, {"l": "kuerzen", "t": "kuerzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Kürze 84/126 vollständig. Zuerst durch 6: ①/②. Dann durch 7: ③/④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [14, 21, 2, 3]}, "h": "Teile Zähler und Nenner durch dieselbe Zahl.", "w": "84 : 6 = 14 und 126 : 6 = 21. Dann durch 7: 14 : 7 = 2 und 21 : 7 = 3. Also 84/126 = 2/3.", "form": "lueckenweg", "zaehlt": "nein", "r": 6877}, {"l": "kuerzen", "t": "kuerzen", "p": "uebung", "s": 2, "g": "darstellung", "y": "luecken", "f": {"text": "Ein Rabatt von 35 % soll als vollständig gekürzter Bruch geschrieben werden. Schreibe den Bruch vollständig gekürzt.", "schablone": "□/□", "hinweis": "Zähler ins erste Kästchen, Nenner ins zweite. Vollständig gekürzt."}, "o": {"werte": [7, 20]}, "h": "Prozent heißt „von hundert“. Kürze danach vollständig.", "w": "35 % = 35/100. Der ggT von 35 und 100 ist 5. 35 : 5 = 7 und 100 : 5 = 20. Also 35 % = 7/20.", "form": "bruecke", "zaehlt": "ja", "r": 6878}, {"l": "kuerzen", "t": "kuerzen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Bruch mit dem Nenner 45 wurde vollständig auf 4/9 gekürzt. Welchen Zähler hatte er vorher?"}, "o": {"wert": 20}, "h": "Mit welcher Zahl wurde gekürzt? Vergleiche die Nenner.", "w": "Der Nenner wurde von 45 auf 9 gekürzt, also durch 5. Der Zähler war 4 · 5 = 20. Probe: 20/45 = 4/9.", "form": "umkehren", "zaehlt": "ja", "r": 6879}, {"l": "verhaeltnis_kuerzen", "t": "verhaeltnis_kuerzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Kürze das Verhältnis 72 : 120 vollständig. Teile beide Zahlen durch 12: ① : ②. Teile dann durch 2: ③ : ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 10, 3, 5]}, "h": "Du teilst beide Zahlen des Verhältnisses durch dieselbe Zahl.", "w": "72 : 12 = 6 und 120 : 12 = 10. Dann durch 2: 3 : 5. Das Verhältnis ist 3 : 5.", "form": "lueckenweg", "zaehlt": "nein", "r": 6880}, {"l": "verhaeltnis_kuerzen", "t": "verhaeltnis_kuerzen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Müsli besteht aus 450 g Haferflocken und 270 g Nüssen. Das Verhältnis Haferflocken : Nüsse wird vollständig gekürzt und als a : b geschrieben. Wie groß ist a + b?"}, "o": {"wert": 8}, "h": "Kürze mit dem ggT von 450 und 270.", "w": "Der ggT von 450 und 270 ist 90. 450 : 90 = 5 und 270 : 90 = 3. Das Verhältnis ist 5 : 3, also a + b = 8.", "form": "anwenden", "zaehlt": "ja", "r": 6881}, {"l": "verhaeltnis_kuerzen", "t": "verhaeltnis_kuerzen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim kürzt das Verhältnis 56 : 98 : 70. Zeile 1: Der ggT von 56, 98 und 70 ist 14. Zeile 2: 56 : 14 = 4, 98 : 14 = 6, 70 : 14 = 5 Zeile 3: Das gekürzte Verhältnis ist 4 : 6 : 5. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Rechne jede Teilung nach.", "w": "98 : 14 = 7, nicht 6. Richtig ist 4 : 7 : 5. Zeile 3 übernimmt nur das Ergebnis aus Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6882}, {"l": "gleichwertig", "t": "gleichwertig", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Das Verhältnis 24 : ? soll gleichwertig zu 6 : 8 sein. Die Erweiterungszahl ist ①. Die gesuchte Zahl ist ②. Die Summe aus 24 und der gesuchten Zahl ist ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 32, 56]}, "h": "Mit welcher Zahl wird aus der 6 die 24?", "w": "24 : 6 = 4. Beide Zahlen werden mit 4 malgenommen: 8 · 4 = 32. 24 : 32 ist gleichwertig zu 6 : 8. Die Summe ist 24 + 32 = 56.", "form": "lueckenweg", "zaehlt": "nein", "r": 6883}, {"l": "gleichwertig", "t": "gleichwertig", "p": "uebung", "s": 2, "g": "darstellung", "y": "luecken", "f": {"text": "Eine Farbmischung besteht aus 12 Teilen Blau und 18 Teilen Weiß. Teilst du beide Zahlen durch dieselbe Zahl, bleibt die Mischung gleich. Welcher Bruchteil der Mischung ist Blau? Schreibe ihn als vollständig gekürzten Bruch.", "schablone": "□/□", "hinweis": "Zähler ins erste Kästchen, Nenner ins zweite. Vollständig gekürzt."}, "o": {"werte": [2, 5]}, "h": "Wie viele gleiche Teile hat die ganze Mischung? Kürze danach vollständig.", "w": "12 Teile Blau und 18 Teile Weiß sind zusammen 30 Teile. Es gilt 12 : 18 = 2 : 3, also sind 2 von 5 Teilen blau. Rechnung: 12/30 der Mischung, gekürzt durch 6: 2/5.", "form": "bruecke", "zaehlt": "ja", "r": 6884}, {"l": "gleichwertig", "t": "gleichwertig", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Auf einer Karte entsprechen 3 cm in Wirklichkeit 12 km. Zwei Orte sind auf der Karte 8,5 cm voneinander entfernt. Wie weit sind sie in Wirklichkeit voneinander entfernt, in Kilometern?"}, "o": {"wert": 34, "einheit": "km"}, "h": "Wie viele Kilometer entsprechen 1 cm auf der Karte?", "w": "3 cm : 12 km ist gleichwertig zu 1 cm : 4 km. 8,5 cm entsprechen 8,5 · 4 km = 34 km.", "form": "anwenden", "zaehlt": "ja", "r": 6885}, {"l": "gemischte_zahlen", "t": "gemischte_zahlen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Schreibe 59/8 als gemischte Zahl. Die 8 passt ganz ① Mal in 59. Der Rest ist ②. Also ist 59/8 = ① + ②/8. Bis zur nächsten ganzen Zahl fehlen noch ③ Achtel.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 3, 5]}, "h": "Wie oft passt der Nenner ganz in den Zähler?", "w": "59 : 8 = 7 Rest 3. Die gemischte Zahl ist 7 3/8. Bis zur 8 fehlen 8 − 3 = 5 Achtel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6886}, {"l": "gemischte_zahlen", "t": "gemischte_zahlen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Brett ist 2 3/4 m lang. Daraus werden Stücke von je 1/4 m Länge gesägt. Wie viele Stücke ergibt das?"}, "o": {"wert": 11}, "h": "Wie viele Viertelmeter sind ein ganzer Meter?", "w": "Ein Meter hat 4 Viertel. 2 m sind 8 Viertel, dazu 3 Viertel: 8 + 3 = 11 Stücke.", "form": "anwenden", "zaehlt": "ja", "r": 6887}, {"l": "gemischte_zahlen", "t": "gemischte_zahlen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Tina rechnet 2 1/3 + 1 5/6. Zeile 1: 2 1/3 + 1 5/6 = 2 2/6 + 1 5/6 Zeile 2: = 3 + 7/6 Zeile 3: = 3 1/6 In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Was passiert, wenn der Bruchteil größer als ein Ganzes ist?", "w": "7/6 = 1 1/6. Man muss das Ganze zu den 3 dazuzählen: 3 + 1 1/6 = 4 1/6. In Zeile 3 ging das Ganze verloren.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6888}, {"l": "kgv", "t": "kgv", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bestimme den Hauptnenner von 5/6 und 3/8. Das kleinste gemeinsame Vielfache von 6 und 8 ist ①. Erweiterst du 5/6 darauf, ist der neue Zähler ②. Erweiterst du 3/8 darauf, ist der neue Zähler ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [24, 20, 9]}, "h": "Schreibe die Vielfachen von 8 auf, bis eines auch in der 6er-Reihe steht.", "w": "Vielfache von 8: 8, 16, 24. 24 steht auch in der 6er-Reihe. 5/6 = 20/24 (mit 4 erweitert) und 3/8 = 9/24 (mit 3 erweitert).", "form": "lueckenweg", "zaehlt": "nein", "r": 6889}, {"l": "kgv", "t": "kgv", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Zwei Busse starten um 8:00 Uhr gemeinsam an der Haltestelle. Der eine Bus fährt alle 12 Minuten ab, der andere alle 18 Minuten. Nach wie vielen Minuten fahren beide zum ersten Mal wieder gleichzeitig ab?"}, "o": {"wert": 36, "einheit": "min"}, "h": "Gesucht ist eine Zahl, die in der 12er- und der 18er-Reihe vorkommt.", "w": "Vielfache von 18: 18, 36. 36 ist auch ein Vielfaches von 12 (3 · 12). Nach 36 Minuten fahren beide wieder gleichzeitig ab.", "form": "anwenden", "zaehlt": "ja", "r": 6890}, {"l": "kgv", "t": "kgv", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ben bringt 4/15 und 3/10 auf einen gemeinsamen Nenner. Zeile 1: Vielfache von 15: 15, 30, 45 Zeile 2: Vielfache von 10: 10, 20, 30 Zeile 3: Der Hauptnenner ist 15 · 10 = 150 Zeile 4: 4/15 = 40/150 und 3/10 = 45/150 In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "In welchen beiden Reihen taucht die erste gemeinsame Zahl auf?", "w": "Das kleinste gemeinsame Vielfache steht schon in Zeile 1 und 2: 30. 150 ist zwar ein gemeinsames Vielfaches, aber nicht das kleinste. Zeile 4 rechnet mit 150 richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6891}, {"l": "vergleichen", "t": "vergleichen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Vergleiche 5/6 und 7/9. Der Hauptnenner ist ①. Dann ist 5/6 = ②/① und 7/9 = ③/①. Der Bruch mit dem größeren Zähler ist der größere.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [18, 15, 14]}, "h": "Suche das kleinste gemeinsame Vielfache von 6 und 9.", "w": "Hauptnenner 18. 5/6 = 15/18 und 7/9 = 14/18. 15 ist größer als 14, also ist 5/6 größer als 7/9.", "form": "lueckenweg", "zaehlt": "nein", "r": 6892}, {"l": "vergleichen", "t": "vergleichen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Vergleiche 11/12 und 13/14. Weg A: Erweitere beide Brüche auf den Nenner 84. Weg B: Prüfe, wie viel jedem Bruch bis zum Ganzen fehlt (1/12 und 1/14). Um wie viele Vierundachtzigstel ist der größere Bruch größer als der kleinere?"}, "o": {"wert": 1}, "h": "Wie viele 84stel sind ein Zwölftel, wie viele ein Vierzehntel?", "w": "Weg A: 11/12 = 77/84 und 13/14 = 78/84. Unterschied: 1/84. Weg B: Es fehlen 7/84 und 6/84; 13/14 fehlt weniger, ist also um 1/84 größer.", "form": "zwei_wege", "zaehlt": "ja", "r": 6893}, {"l": "vergleichen", "t": "vergleichen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Alex und Bea hatten beide 48 € Taschengeld. Alex gibt 3/8 davon für Eis aus, Bea gibt 5/12 davon aus. Wie viel Euro hat Bea mehr ausgegeben als Alex?"}, "o": {"wert": 2, "einheit": "€"}, "h": "Rechne beide Beträge aus und vergleiche sie.", "w": "Alex: 48 € : 8 · 3 = 18 €. Bea: 48 € : 12 · 5 = 20 €. Unterschied: 20 € − 18 € = 2 €.", "form": "anwenden", "zaehlt": "ja", "r": 6894}, {"l": "zahlenstrahl", "t": "zahlenstrahl", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Strecke von 0 bis 1 ist in 15 gleiche Abschnitte geteilt. Der Punkt P liegt nach 10 Abschnitten, also bei 10/15. Der ggT von 10 und 15 ist ①. Gekürzt liegt P bei ②/③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, 2, 3]}, "h": "Welche größte Zahl steckt in 10 und in 15?", "w": "Der ggT von 10 und 15 ist 5. 10 : 5 = 2 und 15 : 5 = 3. P liegt bei 2/3.", "form": "lueckenweg", "zaehlt": "nein", "r": 6895}, {"l": "zahlenstrahl", "t": "zahlenstrahl", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Zwischen den Beschriftungen 0 und 1 liegen auf einem Zahlenstrahl 8 gleich lange Abschnitte. Der Punkt P liegt 13 Abschnitte rechts von 0. Welche Dezimalzahl gehört zu P?"}, "o": {"wert": 1.625}, "h": "Wie lang ist ein Abschnitt?", "w": "Ein Abschnitt ist 1 : 8 = 0,125 lang. 13 Abschnitte sind 13 · 0,125 = 1,625. P liegt zwischen 1 und 2, bei 1 5/8 = 1,625.", "form": "bruecke", "zaehlt": "ja", "r": 6896}, {"l": "zahlenstrahl", "t": "zahlenstrahl", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "luecken", "f": {"text": "Auf dem Zahlenstrahl liegt B bei 5/6. Der Punkt M bei 1/2 ist die Mitte der Strecke von A bis B. Wo liegt A? Schreibe A als vollständig gekürzten Bruch.", "schablone": "□/□", "hinweis": "Zähler ins erste Kästchen, Nenner ins zweite. Vollständig gekürzt."}, "o": {"werte": [1, 6]}, "h": "Von A bis M ist der Weg genauso lang wie von M bis B.", "w": "Von M bis B sind es 5/6 − 1/2 = 1/3. A liegt genauso weit links von M: 1/2 − 1/3 = 1/6.", "form": "umkehren", "zaehlt": "ja", "r": 6897}, {"l": "zahlbereiche", "t": "zahlbereiche", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Auf dem Zahlenstrahl ist die Strecke von −3 bis 1 in Schritte der Länge 0,5 geteilt. Von −3 bis 0 sind es ① Schritte, von 0 bis 1 sind es ② Schritte, zusammen also ③ Schritte. Ohne die beiden Endpunkte liegen ④ Teilpunkte dazwischen.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [6, 2, 8, 7]}, "h": "Wie viele Schritte der Länge 0,5 passen in eine ganze Einheit?", "w": "Eine ganze Einheit hat 2 Schritte der Länge 0,5. Von −3 bis 0 sind es 3 Einheiten, also 6 Schritte. Von 0 bis 1 sind es 2 Schritte. Zusammen 8 Schritte. Dabei gibt es 9 Teilpunkte, mit den beiden Endpunkten; ohne sie bleiben 7.", "form": "lueckenweg", "zaehlt": "nein", "r": 6898}, {"l": "zahlbereiche", "t": "zahlbereiche", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die ganze Zahl −3 soll als Bruch mit dem Nenner 4 geschrieben werden: −3 = ?/4. Welche Zahl steht im Zähler?"}, "o": {"wert": -12}, "h": "Du kannst −3 als −3/1 schreiben und dann erweitern.", "w": "−3 = −3/1. Erweitern mit 4 ergibt −12/4. Der Zähler ist −12.", "form": "bruecke", "zaehlt": "ja", "r": 6899}, {"l": "zahlbereiche", "t": "zahlbereiche", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Die Temperatur liegt bei −3 1/2 °C und sinkt dann um 2 3/4 Grad. Wie viel °C sind es danach?"}, "o": {"wert": -6.25, "einheit": "°C"}, "h": "Beim Sinken wird die Temperatur kleiner.", "w": "−3,5 − 2,75 = −6,25. Die Temperatur beträgt −6,25 °C.", "form": "anwenden", "zaehlt": "ja", "r": 6900}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Lena behauptet: 3/5 = 22/40. Prüfe die Aussage, indem du 3/5 auf den Nenner 40 erweiterst. Die Erweiterungszahl ist ①. Der neue Zähler ist ②. Lenas Zähler 22 weicht davon um ③ ab.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [8, 24, 2]}, "h": "Mit welcher Zahl wird aus 5 die 40?", "w": "40 : 5 = 8. 3 · 8 = 24, also 3/5 = 24/40. Lena hat 22 geschrieben, das sind 2 zu wenig: Die Aussage ist falsch.", "form": "lueckenweg", "zaehlt": "nein", "r": 6901}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du willst prüfen, ob 14/21 und 2/3 gleich groß sind. Welcher Weg zeigt es sicher?"}, "a": ["Prüfen, ob sich Zähler und Nenner um dieselbe Zahl unterscheiden (14 − 2 und 21 − 3)", "Prüfen, ob 14 größer ist als 2", "14/21 durch 7 kürzen und das Ergebnis mit 2/3 vergleichen", "Prüfen, ob 14 + 21 so groß ist wie 2 + 3"], "o": {"index": 2}, "h": "Erweitern und Kürzen ändern den Wert nicht.", "w": "Beim Kürzen werden Zähler und Nenner durch dieselbe Zahl geteilt: 14 : 7 = 2 und 21 : 7 = 3. Das ergibt 2/3. Differenzen oder Summen sagen nichts über den Wert.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 6902}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Lena vergleicht 3/8 und 3/5. Zeile 1: Beide Brüche haben den Zähler 3. Zeile 2: Je größer der Nenner, desto größer der Bruch. Zeile 3: Also ist 3/8 größer als 3/5. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Was passiert mit den Teilen, wenn man das Ganze in mehr Teile teilt?", "w": "Je mehr Teile das Ganze hat, desto kleiner ist jedes Teil. Bei gleichem Zähler ist der Bruch mit dem größeren Nenner kleiner: 3/5 ist größer als 3/8.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6903}]$auf$::jsonb),
    (10, 'bruch.dezimal', 591, 24, $auf$[{"l": "stellenwerte", "t": "stellenwerte", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Zahl hat 6 Einer, 2 Zehntel und 15 Tausendstel. Bündele die 15 Tausendstel: Das sind ① Hundertstel und ② Tausendstel. Schreibe die Zahl mit genau drei Nachkommastellen. Die ganze Zahl, die entsteht, wenn du das Komma weglässt, ist ③. Auf Hundertstel gerundet sind es ④ Hundertstel.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [1, 5, 6215, 622]}, "h": "Zehn Tausendstel sind ein Hundertstel.", "w": "15 Tausendstel = 1 Hundertstel und 5 Tausendstel. Die Zahl ist 6,215. Ohne Komma: 6215. Auf Hundertstel gerundet: 6,22, das sind 622 Hundertstel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6592}, {"l": "stellenwerte", "t": "stellenwerte", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Die Stoppuhr zeigt 12,07 Sekunden. Wie viele Hundertstelsekunden sind das?"}, "o": {"wert": 1207, "einheit": "Hundertstelsekunden"}, "h": "Wie viele Hundertstel passen in eine ganze Sekunde?", "w": "Eine Sekunde hat 100 Hundertstelsekunden. 12 · 100 = 1200, dazu 7: 1207 Hundertstelsekunden.", "form": "anwenden", "zaehlt": "ja", "r": 6593}, {"l": "stellenwerte", "t": "stellenwerte", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Jonas schreibt „3 Zehntel und 5 Hundertstel“ als Dezimalzahl. Zeile 1: 3 Zehntel = 0,3 Zeile 2: 5 Hundertstel = 0,5 Zeile 3: 0,3 + 0,5 = 0,8 In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Welche Stelle hinter dem Komma gehört zu den Hundertsteln?", "w": "5 Hundertstel sind 0,05. Zusammen: 0,3 + 0,05 = 0,35. In Zeile 2 steht die 5 an der Zehntelstelle. Zeile 3 rechnet damit richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6594}, {"l": "vergleichen_ordnen", "t": "vergleichen_ordnen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Vergleiche 0,45 und 0,5 als Tausendstel. 0,45 sind ① Tausendstel. 0,5 sind ② Tausendstel. Die größere Zahl ist um ③ Tausendstel größer. Der Unterschied sind ④ Hundertstel.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [450, 500, 50, 5]}, "h": "Wie viele Tausendstel sind ein Zehntel, wie viele ein Hundertstel?", "w": "0,45 = 450/1000 und 0,5 = 500/1000. 500 − 450 = 50. Also ist 0,5 größer als 0,45, um 50 Tausendstel. 50 Tausendstel sind 5 Hundertstel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6595}, {"l": "vergleichen_ordnen", "t": "vergleichen_ordnen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du willst zwei Dezimalzahlen vergleichen, zum Beispiel 0,8 und 0,75. Welcher Weg entscheidet für jedes Paar nichtnegativer Dezimalzahlen richtig?"}, "a": ["Die Zahlen hinter dem Komma wie ganze Zahlen vergleichen: 8 und 75.", "Rechts vom Komma bei Bedarf Nullen anhängen, bis beide Zahlen gleich viele Nachkommastellen haben. Dann bei beiden das Komma streichen und die ganzen Zahlen vergleichen. Beim Beispiel vergleichst du 80 mit 75.", "Die Ziffern zählen: Die Zahl mit mehr Ziffern ist die größere."], "o": {"index": 1}, "h": "Schreibe beide Zahlen mit gleich vielen Nachkommastellen.", "w": "Hänge Nullen an, bis beide Zahlen gleich viele Nachkommastellen haben, streiche dann das Komma und vergleiche die ganzen Zahlen. Beim Beispiel: 0,8 = 0,80 und 0,75, also 80 und 75. Es ist 80 > 75, also 0,8 > 0,75. Das klappt für jedes Paar, z. B. 0,751 und 0,759: 751 < 759. Die Länge der Ziffernfolge sagt nichts über die Größe.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 6596}, {"l": "vergleichen_ordnen", "t": "vergleichen_ordnen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Drei Papierflieger fliegen 4,35 m, 4,5 m und 4,305 m weit. Um wie viele Zentimeter ist der weiteste Flug weiter als der kürzeste?"}, "o": {"wert": 19.5, "einheit": "cm"}, "h": "Welcher Flug ist der weiteste, welcher der kürzeste? Schreibe die Zahlen mit gleich vielen Stellen.", "w": "Mit drei Nachkommastellen: 4,350 m, 4,500 m, 4,305 m. Weitester: 4,5 m, kürzester: 4,305 m. Unterschied 0,195 m = 19,5 cm.", "form": "anwenden", "zaehlt": "ja", "r": 6597}, {"l": "runden", "t": "runden", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Runde 4,3652 auf Hundertstel. Die Ziffer an der Tausendstelstelle ist ①. Gerundet sind es ② Hundertstel. Die Rundung ändert die Zahl um ③ Zehntausendstel.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [5, 437, 48]}, "h": "Über die Rundung entscheidet die Ziffer direkt hinter der Rundungsstelle.", "w": "An der Tausendstelstelle steht 5, es wird aufgerundet: 4,37 sind 437 Hundertstel. 4,37 − 4,3652 = 0,0048, das sind 48 Zehntausendstel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6598}, {"l": "runden", "t": "runden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Beim Tanken kommen 38,45 Liter in den Tank. Ein Liter kostet 1,759 €. Berechne den Preis und runde auf ganze Cent. Wie viel Euro zahlst du?"}, "o": {"wert": 67.63, "einheit": "€"}, "h": "Rechne zuerst genau und runde erst am Ende.", "w": "38,45 · 1,759 = 67,63355. Auf Cent gerundet: 67,63 €, denn die dritte Nachkommastelle ist 3.", "form": "anwenden", "zaehlt": "ja", "r": 6599}, {"l": "runden", "t": "runden", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Mira rundet 3,7449 auf Hundertstel. Zeile 1: Die Ziffer an der Tausendstelstelle ist 4. Zeile 2: 4 ist kleiner als 5, also wird abgerundet. Zeile 3: 3,7449 ≈ 3,75 In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Prüfe die Rundung noch einmal mit der Zahl.", "w": "Es wird abgerundet, die Hundertstelziffer bleibt 4: 3,7449 ≈ 3,74. In Zeile 3 steht das Aufrunden trotz richtiger Regel.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6600}, {"l": "bruch_zu_dezimal", "t": "bruch_zu_dezimal", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Schreibe 7/8 als Dezimalzahl. Erweitere auf den Nenner 1000. Die Erweiterungszahl ist ①. Der neue Zähler ist ②. Er gibt die Tausendstel an. Auf Hundertstel gerundet sind es ③ Hundertstel.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [125, 875, 88]}, "h": "Mit welcher Zahl wird aus 8 die 1000?", "w": "1000 : 8 = 125. 7 · 125 = 875. Also 7/8 = 875/1000 = 0,875. Auf Hundertstel gerundet: 0,88, das sind 88 Hundertstel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6601}, {"l": "bruch_zu_dezimal", "t": "bruch_zu_dezimal", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Teile 7 durch 16 schriftlich und lies die Dezimalzahl ab. Weg B: Erweitere 7/16 auf den Nenner 10 000. Wie viele Zehntausendstel sind 7/16?"}, "o": {"wert": 4375}, "h": "Beide Wege liefern dieselbe Zahl. Mit welcher Zahl wird 16 zu 10 000?", "w": "Weg A: 7 : 16 = 0,4375, das sind 4375 Zehntausendstel. Weg B: 10 000 : 16 = 625 und 7 · 625 = 4375. Also 7/16 = 4375/10 000.", "form": "zwei_wege", "zaehlt": "ja", "r": 6602}, {"l": "bruch_zu_dezimal", "t": "bruch_zu_dezimal", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Der Bruch ?/16 hat den Wert 0,6875. Welche Zahl steht an der Stelle des Fragezeichens?"}, "o": {"wert": 11}, "h": "Der Bruch bedeutet Zähler : Nenner. Wie hängen Zähler, Nenner und Wert zusammen?", "w": "Zähler : 16 = 0,6875. Also ist der Zähler 0,6875 · 16 = 11. Probe: 11 : 16 = 0,6875.", "form": "umkehren", "zaehlt": "ja", "r": 6603}, {"l": "dezimal_zu_bruch", "t": "dezimal_zu_bruch", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Schreibe 0,36 als vollständig gekürzten Bruch. Zuerst 36/100. Der ggT von 36 und 100 ist ①. Gekürzt ist der Bruch ②/③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [4, 9, 25]}, "h": "Welche größte Zahl steckt in 36 und in 100?", "w": "36/100: der ggT ist 4. 36 : 4 = 9 und 100 : 4 = 25. Also 0,36 = 9/25.", "form": "lueckenweg", "zaehlt": "nein", "r": 6604}, {"l": "dezimal_zu_bruch", "t": "dezimal_zu_bruch", "p": "uebung", "s": 2, "g": "darstellung", "y": "luecken", "f": {"text": "Auf einem Messbecher steht 0,125 Liter. Schreibe 0,125 als vollständig gekürzten Bruch.", "schablone": "□/□", "hinweis": "Zähler ins erste Kästchen, Nenner ins zweite. Vollständig gekürzt."}, "o": {"werte": [1, 8]}, "h": "0,125 sind 125 Tausendstel. Kürze mit dem ggT von 125 und 1000.", "w": "0,125 = 125/1000. Der ggT ist 125. 125 : 125 = 1 und 1000 : 125 = 8. Also 0,125 = 1/8.", "form": "bruecke", "zaehlt": "ja", "r": 6605}, {"l": "dezimal_zu_bruch", "t": "dezimal_zu_bruch", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Peter schreibt 0,045 als Bruch. Zeile 1: 0,045 hat drei Nachkommastellen, also ist der Nenner 1000. Zeile 2: 0,045 = 45/100 Zeile 3: 45/100 = 9/20 In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wie viele Stellen hat 0,045 hinter dem Komma?", "w": "0,045 = 45/1000 = 9/200. In Zeile 2 steht der Nenner 100 statt 1000, obwohl Zeile 1 es richtig sagt. Zeile 3 kürzt 45/100 richtig.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6606}, {"l": "merkwerte", "t": "merkwerte", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du weißt: 1/5 = 0,2. Also sind 3/5 genau ① Zehntel und 4/5 genau ② Zehntel. Zusammen sind 3/5 + 4/5 genau ③ Zehntel. Als Hundertstel sind das ④ Hundertstel.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [6, 8, 14, 140]}, "h": "Ein Fünftel sind zwei Zehntel.", "w": "3/5 = 3 · 0,2 = 0,6, das sind 6 Zehntel. 4/5 sind 8 Zehntel. Zusammen 14 Zehntel, also 1,4. Das sind 140 Hundertstel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6607}, {"l": "merkwerte", "t": "merkwerte", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Rechne 5/8 als Dezimalzahl und vergleiche mit 0,62. Um wie viele Tausendstel ist 5/8 größer als 0,62?"}, "o": {"wert": 5}, "h": "Merke dir 1/8 = 0,125.", "w": "5/8 = 5 · 0,125 = 0,625. 0,625 − 0,62 = 0,005, das sind 5 Tausendstel.", "form": "bruecke", "zaehlt": "ja", "r": 6608}, {"l": "merkwerte", "t": "merkwerte", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Berechne 0,375 · 48 auf zwei Wegen. Weg A: Multipliziere 0,375 mit 48. Weg B: Nimm 3/8 von 48. Wie groß ist das Ergebnis?"}, "o": {"wert": 18}, "h": "Beide Wege führen zum selben Ergebnis. Wie viele sind ein Achtel von 48?", "w": "Weg A: 0,375 · 48 = 18. Weg B: 0,375 = 3/8. 48 : 8 = 6 und 3 · 6 = 18.", "form": "zwei_wege", "zaehlt": "ja", "r": 6609}, {"l": "periodisch", "t": "periodisch", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Rechne 5 : 6. Nach dem Komma steht zuerst die Ziffer ①. Danach wiederholt sich immer dieselbe Ziffer ②. Auf Hundertstel gerundet sind das ③ Hundertstel. Auf Tausendstel gerundet sind das ④ Tausendstel.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [8, 3, 83, 833]}, "h": "Teile 50 durch 6 und achte auf den Rest.", "w": "5 : 6 = 0,8333… Die 8 steht einmal, dann wiederholt sich die 3. Gerundet auf Hundertstel: 0,83, das sind 83 Hundertstel (die nächste Ziffer 3 rundet ab). Auf Tausendstel: 0,833, das sind 833 Tausendstel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6610}, {"l": "periodisch", "t": "periodisch", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Dezimalzahl 0,272727… (die Ziffern 27 wiederholen sich) ist gleich ?/11. Welche Zahl steht im Zähler?"}, "o": {"wert": 3}, "h": "Teile für kleine Zähler Z : 11 schriftlich und vergleiche mit 0,2727…", "w": "3 : 11 = 0,272727… Also ist 0,272727… = 3/11. Der Zähler ist 3.", "form": "bruecke", "zaehlt": "ja", "r": 6611}, {"l": "periodisch", "t": "periodisch", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Mia will wissen, ob 7/20 endlich oder periodisch ist. Zeile 1: Der Nenner ist 20 = 2 · 2 · 3. Zeile 2: Der Nenner hat den Primfaktor 3, der nicht in 10 steckt. Zeile 3: Also ist 7/20 eine periodische Dezimalzahl. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Zerlege 20 noch einmal in Primfaktoren.", "w": "20 = 2 · 2 · 5. Der Nenner hat nur die Primfaktoren 2 und 5, also ist 7/20 = 0,35 endlich. In Zeile 1 steht 3 statt 5.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6612}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Tom behauptet: 0,06 = 1/6. Prüfe die Aussage. 0,06 sind 6 Hundertstel. In Tausendsteln sind das ① Tausendstel. Der Bruch ①/1000 wird vollständig gekürzt zu ②/③. Vergleiche ihn mit Toms Bruch.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [60, 3, 50]}, "h": "Ein Hundertstel sind zehn Tausendstel.", "w": "6 Hundertstel = 60 Tausendstel. 60/1000 wird durch 20 gekürzt: 3/50. Also 0,06 = 3/50, nicht 1/6: Toms Aussage ist falsch.", "form": "lueckenweg", "zaehlt": "nein", "r": 6613}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du willst prüfen, ob 0,3 und 0,30 gleich groß sind. Welcher Weg zeigt es sicher?"}, "a": ["0,3 in Hundertstel umschreiben (3 Zehntel sind 30 Hundertstel) und mit 0,30 vergleichen.", "Die Zahlen 3 und 30 vergleichen: 30 ist größer, also ist 0,30 größer.", "Die Stellen zählen: 0,3 hat weniger Stellen, also ist es kleiner.", "Die Schreibweise vergleichen: Sie ist verschieden, also sind die Werte verschieden."], "o": {"index": 0}, "h": "Wie viele Hundertstel sind drei Zehntel?", "w": "Ein Zehntel sind 10 Hundertstel. 3 Zehntel sind 30 Hundertstel. Eine angehängte Null nach der letzten Nachkommastelle ändert den Wert nicht.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 6614}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Dezimalzahl hat 3 Einer, 2 Zehntel und ? Hundertstel und keine weitere Stelle. Auf Zehntel gerundet ist sie 3,3. Welche ist die kleinste Ziffer, die an der Stelle des Fragezeichens stehen kann?"}, "o": {"wert": 5}, "h": "Ab welcher Ziffer wird aufgerundet?", "w": "Aufgerundet wird ab der Ziffer 5. 3,25 ≈ 3,3. Mit 4 würde abgerundet: 3,24 ≈ 3,2.", "form": "umkehren", "zaehlt": "ja", "r": 6615}]$auf$::jsonb),
    (11, 'bruch.prozent', 621, 18, $auf$[{"l": "prozent_bedeutung", "t": "prozent_bedeutung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Schreibe 45 % als gekürzten Bruch. 45 % sind 45/100. Der ggT von 45 und 100 ist ①. Der Bruch ist dann ②/③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [5, 9, 20]}, "h": "Prozent heißt „von hundert“.", "w": "45 % = 45/100. Der ggT ist 5. 45 : 5 = 9 und 100 : 5 = 20. Also 45 % = 9/20.", "form": "lueckenweg", "zaehlt": "nein", "r": 6622}, {"l": "prozent_bedeutung", "t": "prozent_bedeutung", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Ein Streifen besteht aus 40 gleich großen Kästchen. 14 Kästchen sind gefärbt. Wie viel Prozent des Streifens sind gefärbt?"}, "o": {"wert": 35, "einheit": "%"}, "h": "Wie viele Kästchen wären 100 Prozent? Rechne den Anteil in Hundertstel um.", "w": "14 von 40 ist 14/40 = 35/100. Das sind 35 %. Probe: 1 % sind 0,4 Kästchen, 0,4 · 35 = 14.", "form": "bruecke", "zaehlt": "ja", "r": 6623}, {"l": "prozent_bedeutung", "t": "prozent_bedeutung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Aysel schreibt 0,6 % als Dezimalzahl. Zeile 1: 0,6 % = 6/100 Zeile 2: 6/100 = 0,06 Zeile 3: Also ist 0,6 % = 0,06. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie viele Hundertstel sind 0,6 Hundertstel? Ein Prozent ist ein Hundertstel.", "w": "0,6 % = 0,6/100 = 6/1000 = 0,006. In Zeile 1 steht 6/100, das wären 6 %. Zeile 2 stimmt für sich (6/100 = 0,06), Zeile 3 übernimmt die falsche Gleichsetzung aus Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6624}, {"l": "prozentwert", "t": "prozentwert", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 15 % von 200 €. Ein Prozent sind ① €. 15 % sind ② €. Nach dem Abziehen dieser 15 % bleiben ③ €.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [2, 30, 170]}, "h": "Teile zuerst durch 100, um ein Prozent zu erhalten.", "w": "200 € : 100 = 2 € ist ein Prozent. 15 · 2 € = 30 €. Es bleiben 200 € − 30 € = 170 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 6625}, {"l": "prozentwert", "t": "prozentwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 35 % von 80 m. Weg A: Rechne 35/100 · 80. Weg B: Zerlege 35 % in 10 % + 10 % + 10 % + 5 % und rechne mit 10 % = ein Zehntel. Wie viele Meter sind es?"}, "o": {"wert": 28, "einheit": "m"}, "h": "Beide Wege liefern dasselbe Ergebnis. Wie viel sind 10 % von 80 m?", "w": "Weg A: 80 · 35 : 100 = 28. Weg B: 10 % = 8 m, drei mal 10 % = 24 m, 5 % = 4 m. 24 + 4 = 28 m.", "form": "zwei_wege", "zaehlt": "ja", "r": 6626}, {"l": "prozentwert", "t": "prozentwert", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Fahrrad kostet 420 €. Beim Kauf zahlt man 15 % Anzahlung. Der Rest wird in 6 gleich hohen Raten bezahlt. Wie hoch ist eine Rate in Euro?"}, "o": {"wert": 59.5, "einheit": "€"}, "h": "Wie viel Euro bleiben nach der Anzahlung?", "w": "Anzahlung: 15 % von 420 € = 63 €. Rest: 420 € − 63 € = 357 €. Eine Rate: 357 € : 6 = 59,50 €.", "form": "anwenden", "zaehlt": "ja", "r": 6627}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Von 25 Kindern haben 6 ein Haustier. Erweitere 6/25 auf den Nenner 100. Die Erweiterungszahl ist ①. ② % ist der Prozentsatz. Die übrigen Kinder machen ③ % aus.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [4, 24, 76]}, "h": "Mit welcher Zahl wird aus 25 die 100?", "w": "100 : 25 = 4. 6 · 4 = 24, also 24 %. Die übrigen Kinder: 100 % − 24 % = 76 %.", "form": "lueckenweg", "zaehlt": "nein", "r": 6628}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Verein hat 240 Mitglieder. 54 davon sind jünger als 18 Jahre. Wie viel Prozent der Mitglieder sind jünger als 18 Jahre?"}, "o": {"wert": 22.5, "einheit": "%"}, "h": "Teil durch Ganzes, dann in Prozent umrechnen.", "w": "54/240 = 0,225 = 22,5/100. Das sind 22,5 %.", "form": "anwenden", "zaehlt": "ja", "r": 6629}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Der Preis einer Jacke wird von 80 € auf 100 € erhöht. Um wie viel Prozent muss der neue Preis gesenkt werden, damit die Jacke wieder 80 € kostet?"}, "o": {"wert": 20, "einheit": "%"}, "h": "Auf welchen Preis beziehen sich die Prozent bei der Senkung?", "w": "Die Senkung beträgt 20 €. Sie bezieht sich auf den neuen Preis 100 €: 20/100 = 20 %.", "form": "umkehren", "zaehlt": "ja", "r": 6630}, {"l": "grundwert", "t": "grundwert", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "15 % einer Summe sind 45 €. Dann sind 1 % genau ① €. Die ganze Summe ist ② €. Zur Probe: 10 % der Summe sind ③ €.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [3, 300, 30]}, "h": "Rechne zuerst auf ein Prozent zurück.", "w": "45 € : 15 = 3 € sind 1 %. Das Ganze: 100 · 3 € = 300 €. 10 % davon sind 30 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 6631}, {"l": "grundwert", "t": "grundwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du weißt: 18 % einer Größe sind 72. Mit welcher Rechnung findest du die ganze Größe?"}, "a": ["72 · 18 : 100", "72 · 18", "72 − 18", "72 : 18 · 100"], "o": {"index": 3}, "h": "Erst herausfinden, wie viel ein Prozent ist.", "w": "72 : 18 = 4 sind 1 %. Das Ganze sind 100 %: 4 · 100 = 400. Rechnung: 72 : 18 · 100.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 6632}, {"l": "grundwert", "t": "grundwert", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Händler verkauft ein Spiel mit 8 % Gewinn für 135 €. Das ist der Einkaufspreis plus 8 % davon. Wie viel Euro hat das Spiel im Einkauf gekostet?"}, "o": {"wert": 125, "einheit": "€"}, "h": "135 € sind wie viel Prozent des Einkaufspreises?", "w": "Der Verkaufspreis ist 108 % des Einkaufspreises. 135 € : 108 = 1,25 € sind 1 %. 100 % sind 125 €. Probe: 125 € + 10 € = 135 €.", "form": "anwenden", "zaehlt": "ja", "r": 6633}, {"l": "rabatt_aufschlag", "t": "rabatt_aufschlag", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Pullover kostet 80 €. Der Preis steigt um 15 %: Der Aufschlag beträgt ① €, der neue Preis ② €. Danach gibt es 25 % Rabatt auf den neuen Preis. Der Preis ist dann ③ €.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [12, 92, 69]}, "h": "Der Aufschlag ist ein Prozentwert vom alten Preis.", "w": "15 % von 80 € = 12 €. Neuer Preis: 92 €. 25 % Rabatt heißt: 75 % bleiben. 75 % von 92 € = 69 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 6634}, {"l": "rabatt_aufschlag", "t": "rabatt_aufschlag", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Mantel kostet 150 €. Es gibt 30 % Rabatt. Weg A: Berechne den Rabatt in Euro und ziehe ihn ab. Weg B: Berechne direkt, wie viel Prozent des Preises noch zu zahlen sind. Was kostet der Mantel jetzt?"}, "o": {"wert": 105, "einheit": "€"}, "h": "Beide Wege liefern denselben Preis.", "w": "Weg A: 30 % von 150 € = 45 €. 150 € − 45 € = 105 €. Weg B: 100 % − 30 % = 70 %. 70 % von 150 € = 105 €.", "form": "zwei_wege", "zaehlt": "ja", "r": 6635}, {"l": "rabatt_aufschlag", "t": "rabatt_aufschlag", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Fahrrad kostet nach einem Rabatt von 20 % noch 280 €. Wie viel Euro hat es vor dem Rabatt gekostet?"}, "o": {"wert": 350, "einheit": "€"}, "h": "280 € sind wie viel Prozent des ursprünglichen Preises?", "w": "Nach 20 % Rabatt sind noch 80 % zu zahlen. 280 € : 80 = 3,50 € sind 1 %. 100 % sind 350 €. Probe: 20 % von 350 € = 70 €, 350 € − 70 € = 280 €.", "form": "umkehren", "zaehlt": "ja", "r": 6636}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Preis von 100 € steigt um 10 %. Danach sinkt der neue Preis um 10 %. Nach der Erhöhung beträgt der Preis ① €. Nach der Senkung beträgt er ② €. Er liegt dann ③ € unter dem Startpreis.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [110, 99, 1]}, "h": "Die zweiten 10 % beziehen sich auf den neuen Preis.", "w": "Nach +10 %: 110 €. 10 % von 110 € sind 11 €. 110 € − 11 € = 99 €. Das sind 1 € weniger als am Anfang.", "form": "lueckenweg", "zaehlt": "nein", "r": 6637}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "In einem Kreisdiagramm: 40 % der Gäste wählen Kuchen. Max sagt: „Der Kreisausschnitt dafür hat 140°.“ Der ganze Kreis hat 360°. Um wie viel Grad ist Max' Angabe zu klein?"}, "o": {"wert": 4, "einheit": "°"}, "h": "100 % entsprechen dem ganzen Kreis. Berechne zuerst den richtigen Winkel.", "w": "1 % entspricht 3,6°. 40 · 3,6° = 144°. Max' 140° sind 4° zu wenig.", "form": "bruecke", "zaehlt": "ja", "r": 6638}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Mara behauptet: „Steigt ein Preis um 20 % und sinkt danach um 20 %, ist er wieder so hoch wie am Anfang.“ Sie rechnet mit 50 €. Zeile 1: Erhöhung: 50 · 1,2 = 60 € Zeile 2: Senkung: 60 · 0,8 = 48 € Zeile 3: Also 48 € = 50 €, der Preis ist wieder gleich. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Vergleiche die beiden letzten Preise.", "w": "Die zwei Rechnungen stimmen, aber 48 € sind nicht 50 €. Die 20 % der Senkung beziehen sich auf den neuen Preis 60 €, nicht auf 50 €. Der Preis liegt am Ende 2 € unter dem Start.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6639}]$auf$::jsonb),
    (12, 'bruch.rechnen', 830, 36, $auf$[{"l": "brueche_plus_minus", "t": "brueche_plus_minus", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 3/4 + 5/6. Der Hauptnenner ist ①. Die Summe hat dann den Zähler ②. Als gemischte Zahl ist die Summe 1 ③/①.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [12, 19, 7]}, "h": "Suche das kleinste gemeinsame Vielfache der beiden Nenner.", "w": "Hauptnenner 12: 3/4 = 9/12 und 5/6 = 10/12. Summe: 19/12. Davon ist 12/12 ein Ganzes, es bleiben 7/12. Also 1 7/12.", "form": "lueckenweg", "zaehlt": "nein", "r": 6831}, {"l": "brueche_plus_minus", "t": "brueche_plus_minus", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 3 1/4 − 1 5/6. Weg A: Wandle beide Zahlen in unechte Brüche um. Weg B: Rechne die Ganzen und die Brüche getrennt und entbündle bei Bedarf. Wie viele Zwölftel ist das Ergebnis?"}, "o": {"wert": 17}, "h": "Beide Wege führen zu demselben Ergebnis. Der Hauptnenner ist 12.", "w": "Weg A: 3 1/4 = 13/4 = 39/12 und 1 5/6 = 11/6 = 22/12. 39/12 − 22/12 = 17/12. Weg B: 3 3/12 − 1 10/12 = 2 15/12 − 1 10/12 = 1 5/12 = 17/12.", "form": "zwei_wege", "zaehlt": "ja", "r": 6832}, {"l": "brueche_plus_minus", "t": "brueche_plus_minus", "p": "uebung", "s": 3, "g": "transfer", "y": "luecken", "f": {"text": "Ein Wasserbehälter ist zu 2/3 gefüllt. Morgens wird 1/4 des Behälters entnommen, abends wird 1/6 des Behälters aufgefüllt. Welcher Bruchteil des Behälters ist danach gefüllt? Gib den Bruch vollständig gekürzt an.", "schablone": "□/□", "hinweis": "Zähler ins erste Kästchen, Nenner ins zweite. Vollständig gekürzt."}, "o": {"werte": [7, 12]}, "h": "Bringe alle Brüche auf einen Nenner.", "w": "Hauptnenner 12: 2/3 = 8/12, 1/4 = 3/12, 1/6 = 2/12. 8/12 − 3/12 + 2/12 = 7/12.", "form": "anwenden", "zaehlt": "ja", "r": 6833}, {"l": "dezimal_plus_minus", "t": "dezimal_plus_minus", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 12,4 + 3,85 − 7,6 in Hundertsteln. 12,4 sind ① Hundertstel. Die Summe 12,4 + 3,85 sind ② Hundertstel. Nach dem Abziehen von 7,6 bleiben ③ Hundertstel.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [1240, 1625, 865]}, "h": "Schreibe 12,4 als 12,40.", "w": "12,4 = 1240 Hundertstel. 1240 + 385 = 1625. 7,6 = 760 Hundertstel. 1625 − 760 = 865, also 8,65.", "form": "lueckenweg", "zaehlt": "nein", "r": 6834}, {"l": "dezimal_plus_minus", "t": "dezimal_plus_minus", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Beim Einkauf kosten Brot 3,49 €, Käse 12,80 € und Saft 0,99 €. Du bezahlst mit einem 20-Euro-Schein. Wie viel Euro bekommst du zurück?"}, "o": {"wert": 2.72, "einheit": "€"}, "h": "Addiere zuerst alle drei Preise.", "w": "3,49 + 12,80 + 0,99 = 17,28. 20 − 17,28 = 2,72. Du bekommst 2,72 € zurück.", "form": "anwenden", "zaehlt": "ja", "r": 6835}, {"l": "dezimal_plus_minus", "t": "dezimal_plus_minus", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Denke dir eine Zahl x. Addierst du 2,75 und ziehst dann 4,6 ab, erhältst du 3,05. Welche Zahl war x?"}, "o": {"wert": 4.9}, "h": "Rechne rückwärts: Kehre jeden Schritt um, beginnend beim letzten.", "w": "Letzter Schritt „− 4,6“ umkehren: 3,05 + 4,6 = 7,65. Davor „+ 2,75“ umkehren: 7,65 − 2,75 = 4,9. Probe: 4,9 + 2,75 − 4,6 = 3,05.", "form": "umkehren", "zaehlt": "ja", "r": 6836}, {"l": "vorzeichen", "t": "vorzeichen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne (−12) − (−7) + (−9). Minus eine negative Zahl ist Plus: (−12) − (−7) = ①. Dann ① + (−9) = ②. Der Abstand des Ergebnisses von der Null ist ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-5, -14, 14]}, "h": "Eine negative Zahl abziehen heißt ihre Gegenzahl addieren.", "w": "(−12) − (−7) = −12 + 7 = −5. Dann −5 + (−9) = −14. Der Abstand von der Null ist 14.", "form": "lueckenweg", "zaehlt": "nein", "r": 6837}, {"l": "vorzeichen", "t": "vorzeichen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Auf der Zahlengeraden startest du bei −4,5. Du gehst 3,2 Einheiten nach links und danach 6,8 Einheiten nach rechts. Bei welcher Zahl landest du?"}, "o": {"wert": -0.9}, "h": "Schreibe den Weg als Rechnung auf: Links ist minus, rechts ist plus.", "w": "Als Rechnung: −4,5 − 3,2 + 6,8 = −7,7 + 6,8 = −0,9. Du landest bei −0,9.", "form": "bruecke", "zaehlt": "ja", "r": 6838}, {"l": "vorzeichen", "t": "vorzeichen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Tom rechnet (−3,2) − (−0,5). Zeile 1: (−3,2) − (−0,5) = (−3,2) + 0,5 Zeile 2: (−3,2) + 0,5 = −3,7 Zeile 3: Das Ergebnis ist −3,7. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Rechne (−3,2) + 0,5 auf der Zahlengeraden: in welche Richtung gehst du?", "w": "Plus 0,5 heißt 0,5 nach rechts: −3,2 + 0,5 = −2,7. In Zeile 2 wurde 0,5 nach links gegangen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6839}, {"l": "brueche_mal", "t": "brueche_mal", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 10/21 · 9/25. Kürze vor dem Malnehmen über Kreuz: 10 und 25 durch ① und 9 und 21 durch ②. Das Ergebnis ist dann ③/④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [5, 3, 6, 35]}, "h": "Welche größte Zahl teilt 10 und 25? Welche teilt 9 und 21?", "w": "10 : 5 = 2 und 25 : 5 = 5. 9 : 3 = 3 und 21 : 3 = 7. Dann: 2/7 · 3/5 = 6/35.", "form": "lueckenweg", "zaehlt": "nein", "r": 6840}, {"l": "brueche_mal", "t": "brueche_mal", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du sollst 8/15 · 5/12 berechnen. Welcher Weg ist richtig und geschickt?"}, "a": ["Zähler und Nenner einzeln addieren: 13/27", "Mit dem Kehrwert von 5/12 malnehmen: 8/15 · 12/5 = 32/25", "Nur die Zähler malnehmen, den Nenner 15 behalten: 40/15", "Vor dem Malnehmen über Kreuz kürzen: 2/3 · 1/3 = 2/9"], "o": {"index": 3}, "h": "Beim Malnehmen von Brüchen braucht man keinen gemeinsamen Nenner.", "w": "Zähler mal Zähler und Nenner mal Nenner. Vorher kürzen: 8 und 12 durch 4, 5 und 15 durch 5. So bleibt 2/3 · 1/3 = 2/9. Probe: 8/15 · 5/12 = 40/180 = 2/9.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 6841}, {"l": "brueche_mal", "t": "brueche_mal", "p": "uebung", "s": 3, "g": "transfer", "y": "luecken", "f": {"text": "Von einer Torte sind noch 3/4 da. Anna isst davon 2/3. Vom Rest, der dann noch da ist, isst Ben 1/3. Welcher Bruchteil der ganzen Torte bleibt am Ende? Gib den Bruch vollständig gekürzt an.", "schablone": "□/□", "hinweis": "Zähler ins erste Kästchen, Nenner ins zweite. Vollständig gekürzt."}, "o": {"werte": [1, 6]}, "h": "Rechne mit dem Rest, der nach jedem Essen noch da ist.", "w": "Nach Anna: 3/4 · 1/3 = 1/4 der Torte bleibt. Ben isst 1/3 davon, es bleiben 2/3 von 1/4. 2/3 · 1/4 = 2/12 = 1/6.", "form": "anwenden", "zaehlt": "ja", "r": 6842}, {"l": "brueche_geteilt", "t": "brueche_geteilt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 7/12 : 21/16 als Malaufgabe mit dem Kehrwert: 7/12 · 16/21. Zähler mal Zähler ergibt ① und Nenner mal Nenner ergibt ② (noch nicht gekürzt). Gekürzt ist das Ergebnis ③/④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [112, 252, 4, 9]}, "h": "Beim Teilen durch einen Bruch malnimmst du mit seinem Kehrwert.", "w": "7 · 16 = 112 und 12 · 21 = 252. 112/252 wird durch 28 gekürzt: 4/9.", "form": "lueckenweg", "zaehlt": "nein", "r": 6843}, {"l": "brueche_geteilt", "t": "brueche_geteilt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Aus einem Krug mit 3/4 Liter Saft sollen kleine Gläser mit je 1/8 Liter gefüllt werden. Wie viele Gläser werden voll?"}, "o": {"wert": 6}, "h": "Wie oft passt 1/8 in 3/4?", "w": "3/4 : 1/8 = 3/4 · 8 = 6. In 3/4 Liter passen 6 Gläser zu je 1/8 Liter. Probe: 6 · 1/8 = 3/4.", "form": "anwenden", "zaehlt": "ja", "r": 6844}, {"l": "brueche_geteilt", "t": "brueche_geteilt", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "luecken", "f": {"text": "Der Bruch 3/4 wird durch einen Bruch geteilt. Das Ergebnis ist 9/8. Durch welchen Bruch wurde geteilt? Schreibe ihn vollständig gekürzt.", "schablone": "□/□", "hinweis": "Zähler ins erste Kästchen, Nenner ins zweite. Vollständig gekürzt."}, "o": {"werte": [2, 3]}, "h": "Schreibe die Aufgabe als 3/4 : ? = 9/8. Wie kannst du die gesuchte Zahl durch eine Probe finden?", "w": "Gesucht ist x mit 3/4 : x = 9/8. Dann ist x = 3/4 : 9/8 = 3/4 · 8/9 = 24/36 = 2/3. Probe: 3/4 : 2/3 = 3/4 · 3/2 = 9/8.", "form": "umkehren", "zaehlt": "ja", "r": 6845}, {"l": "dezimal_mal", "t": "dezimal_mal", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 3,6 · 0,25. Rechne zuerst ohne Komma: 36 · 25 = ①. Die beiden Faktoren haben zusammen ② Nachkommastellen. Das Ergebnis hat dann ③ Zehntel. Es ist um ④ Hundertstel kleiner als 1.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [900, 3, 9, 10]}, "h": "Zähle die Stellen hinter dem Komma bei beiden Faktoren.", "w": "36 · 25 = 900. 3,6 hat 1 und 0,25 hat 2 Nachkommastellen, zusammen 3. 900 mit 3 Nachkommastellen ist 0,900 = 0,9, das sind 9 Zehntel. 0,9 sind 90 Hundertstel, bis 1 fehlen 100 − 90 = 10 Hundertstel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6846}, {"l": "dezimal_mal", "t": "dezimal_mal", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 0,4 · 0,35 auf zwei Wegen. Weg A: Rechne 4 · 35 und setze das Komma nach den Nachkommastellen. Weg B: Schreibe beide Zahlen als Bruch und multipliziere. Wie lautet das Ergebnis?"}, "o": {"wert": 0.14}, "h": "Wie viele Nachkommastellen haben beide Faktoren zusammen?", "w": "Weg A: 4 · 35 = 140, drei Nachkommastellen: 0,140 = 0,14. Weg B: 4/10 · 35/100 = 140/1000 = 14/100 = 0,14.", "form": "zwei_wege", "zaehlt": "ja", "r": 6847}, {"l": "dezimal_mal", "t": "dezimal_mal", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Kilogramm Birnen kostet 2,40 €. Mia kauft 1,4 kg. An der Kasse bekommt sie 0,50 € Rabatt auf den Gesamtbetrag. Wie viel Euro zahlt sie?"}, "o": {"wert": 2.86, "einheit": "€"}, "h": "Berechne zuerst den Preis für die Birnen.", "w": "1,4 · 2,40 = 3,36. Dann der Rabatt: 3,36 − 0,50 = 2,86. Mia zahlt 2,86 €.", "form": "anwenden", "zaehlt": "ja", "r": 6848}, {"l": "dezimal_geteilt", "t": "dezimal_geteilt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 4,8 : 0,06. Erweitere beide Zahlen mit 100: ① : 6. Das Ergebnis ist ②. Das sind ③ Zehner.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [480, 80, 8]}, "h": "Erweitere so, dass der Teiler eine ganze Zahl wird.", "w": "4,8 · 100 = 480 und 0,06 · 100 = 6. 480 : 6 = 80. 80 sind 8 Zehner.", "form": "lueckenweg", "zaehlt": "nein", "r": 6849}, {"l": "dezimal_geteilt", "t": "dezimal_geteilt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Seil ist 7,2 m lang. Daraus werden Stücke von je 0,35 m geschnitten. Wie viele ganze Stücke ergibt das?"}, "o": {"wert": 20}, "h": "Teile die Länge des Seils durch die Länge eines Stücks.", "w": "7,2 m = 720 cm und 0,35 m = 35 cm. 720 = 20 · 35 + 20 (in cm). Es gibt 20 ganze Stücke, ein Rest von 20 cm = 0,2 m bleibt übrig.", "form": "anwenden", "zaehlt": "ja", "r": 6850}, {"l": "dezimal_geteilt", "t": "dezimal_geteilt", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eva rechnet 1,35 : 0,9. Zeile 1: 1,35 : 0,9 = 135 : 9 Zeile 2: 135 : 9 = 15 Zeile 3: Also ist 1,35 : 0,9 = 15. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Mit welcher Zahl musst du beide Zahlen malnehmen, damit der Teiler 9 wird? Ändert das auch die erste Zahl um dasselbe?", "w": "Erweiterst du beide Zahlen mit 10, steht 13,5 : 9 = 1,5. Wer 1,35 mit 100 und 0,9 mit 10 erweitert, ändert die Aufgabe. Zeile 2 stimmt für sich (135 : 9 = 15), Zeile 3 zieht daraus die falsche Folgerung.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6851}, {"l": "potenzen", "t": "potenzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne (2/5)³. Der Zähler ist 2³ = ①. Der Nenner ist 5³ = ②. Als Dezimalzahl sind das ③ Tausendstel. Auf Hundertstel gerundet sind es ④ Hundertstel.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [8, 125, 64, 6]}, "h": "Beim Potenzieren von Brüchen wird Zähler und Nenner potenziert.", "w": "2³ = 8 und 5³ = 125. (2/5)³ = 8/125. Erweitern mit 8 gibt 64/1000, also 0,064, das sind 64 Tausendstel. Auf Hundertstel gerundet: 0,06, das sind 6 Hundertstel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6852}, {"l": "potenzen", "t": "potenzen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine quadratische Teppichfliese hat die Seitenlänge 2/5 m. Es gilt 1 m² = 100 dm². Wie groß ist ihre Fläche in Quadratdezimetern?"}, "o": {"wert": 16, "einheit": "dm²"}, "h": "Die Fläche eines Quadrats ist Seite mal Seite.", "w": "Fläche = (2/5 m)² = 4/25 m² = 0,16 m². Mal 100: 16 dm².", "form": "anwenden", "zaehlt": "ja", "r": 6853}, {"l": "potenzen", "t": "potenzen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "luecken", "f": {"text": "Eine Zahl a/b hoch 3 ergibt 27/64. Wie heißt die Zahl? Schreibe sie als vollständig gekürzten Bruch.", "schablone": "□/□", "hinweis": "Zähler ins erste Kästchen, Nenner ins zweite. Vollständig gekürzt."}, "o": {"werte": [3, 4]}, "h": "Welche Zahl mal sich selbst mal sich selbst ergibt 27, welche 64?", "w": "3 · 3 · 3 = 27 und 4 · 4 · 4 = 64. Also (3/4)³ = 27/64. Die Zahl ist 3/4.", "form": "umkehren", "zaehlt": "ja", "r": 6854}, {"l": "rechenvorteile", "t": "rechenvorteile", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 4 · 3,7 · 25 geschickt. Zuerst tauschst du die Faktoren und rechnest 4 · 25 = ①. Dann ① · 3,7 = ②. Das sind ③ Zehntel.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [100, 370, 3700]}, "h": "Welche zwei Faktoren ergeben zusammen eine runde Zahl?", "w": "4 · 25 = 100. 100 · 3,7 = 370. Das sind 3700 Zehntel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6855}, {"l": "rechenvorteile", "t": "rechenvorteile", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 98 · 7 auf zwei Wegen. Weg A: Schreibe 98 als 100 − 2 und rechne 100 · 7 − 2 · 7. Weg B: Multipliziere 98 mit 7 schriftlich. Wie groß ist das Produkt?"}, "o": {"wert": 686}, "h": "Beide Wege müssen dasselbe Ergebnis liefern.", "w": "Weg A: 100 · 7 = 700 und 2 · 7 = 14. 700 − 14 = 686. Weg B: 98 · 7 = 686.", "form": "zwei_wege", "zaehlt": "ja", "r": 6856}, {"l": "rechenvorteile", "t": "rechenvorteile", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Lager enthält 25 Kisten. In jeder Kiste stehen 4 Kartons. Jeder Karton wiegt 3,6 kg. Wie viel Kilogramm wiegt alles zusammen?"}, "o": {"wert": 360, "einheit": "kg"}, "h": "Welche beiden Zahlen kannst du zuerst malnehmen, um eine runde Zahl zu erhalten?", "w": "25 · 4 = 100 Kartons. 100 · 3,6 kg = 360 kg.", "form": "anwenden", "zaehlt": "ja", "r": 6857}, {"l": "gemischt", "t": "gemischt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 8/9 − 3/4 · 2/9. Punkt vor Strich: Das Produkt ist ①/② (noch nicht gekürzt). Das Ergebnis der ganzen Aufgabe ist ③/④ (gekürzt).", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [6, 36, 13, 18]}, "h": "Rechne zuerst das Mal. Dann bringe beide Brüche auf einen Nenner.", "w": "3/4 · 2/9 = 6/36 = 1/6. 8/9 = 16/18 und 1/6 = 3/18. 16/18 − 3/18 = 13/18.", "form": "lueckenweg", "zaehlt": "nein", "r": 6858}, {"l": "gemischt", "t": "gemischt", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Welcher Term passt zu dem Satz: „Von 7/8 wird das Produkt aus 1/2 und 3/4 abgezogen“?"}, "a": ["(7/8 − 1/2) · 3/4", "7/8 − 1/2 · 3/4", "7/8 − 1/2 − 3/4", "7/8 · 1/2 − 3/4"], "o": {"index": 1}, "h": "Was wird abgezogen? Es ist ein Produkt aus zwei Zahlen.", "w": "Das Produkt aus 1/2 und 3/4 ist 1/2 · 3/4. Dieses Produkt wird von 7/8 abgezogen: 7/8 − 1/2 · 3/4 = 7/8 − 3/8 = 1/2.", "form": "bruecke", "zaehlt": "ja", "r": 6859}, {"l": "gemischt", "t": "gemischt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Aus 60 Litern Saft werden 1/3 in Flaschen gefüllt. Vom Rest werden 3/4 in Kanister gefüllt. Wie viele Liter bleiben übrig?"}, "o": {"wert": 10, "einheit": "l"}, "h": "Welcher Rest bleibt nach dem Abfüllen in Flaschen?", "w": "Flaschen: 60 l : 3 = 20 l. Rest: 40 l. Kanister: 40 l : 4 · 3 = 30 l. Übrig: 40 l − 30 l = 10 l.", "form": "anwenden", "zaehlt": "ja", "r": 6860}, {"l": "fehler_finden", "t": "fehler_finden", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kind rechnet 7/8 + 5/6 = 12/14, weil es Zähler und Nenner einzeln addiert. Richtig ist: Der Hauptnenner ist ①. Die Summe hat dann den Zähler ②. Als gemischte Zahl ist die Summe 1 ③/①.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [24, 41, 17]}, "h": "Brüche mit verschiedenen Nennern muss man erst gleichnamig machen.", "w": "Hauptnenner 24: 7/8 = 21/24 und 5/6 = 20/24. 21 + 20 = 41. Die Summe ist 41/24 = 1 17/24.", "form": "lueckenweg", "zaehlt": "nein", "r": 6861}, {"l": "fehler_finden", "t": "fehler_finden", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein Kind rechnet 0,2 · 0,3 = 0,6. Mit welcher Überlegung prüfst du am sichersten, ob das stimmt?"}, "a": ["Malnehmen vergrößert immer. Das Ergebnis muss größer sein als beide Faktoren, 0,6 ist größer als 0,2 und 0,3.", "Ohne Komma rechnen (2 · 3 = 6). Die beiden Faktoren haben zusammen 2 Nachkommastellen, also hat auch das Ergebnis 2: 0,06.", "Das Komma bleibt an der Stelle wie beim ersten Faktor: 0,2 · 0,3 = 0,6.", "0,2 + 0,3 = 0,5 rechnen und prüfen, ob das Ergebnis in der Nähe liegt."], "o": {"index": 1}, "h": "Wie viele Nachkommastellen haben die beiden Faktoren zusammen?", "w": "2 · 3 = 6, und 0,2 und 0,3 haben zusammen 2 Nachkommastellen. Also ist 0,2 · 0,3 = 0,06, nicht 0,6. Probe mit Brüchen: 2/10 · 3/10 = 6/100.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 6862}, {"l": "fehler_finden", "t": "fehler_finden", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Karl rechnet 2/3 : 4/9. Zeile 1: 2/3 : 4/9 = 2/3 · 9/4 Zeile 2: = 18/12 Zeile 3: Gekürzt ist das 2/3. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Kürze 18/12 noch einmal. Durch welche Zahl teilst du?", "w": "18/12 wird durch 6 gekürzt: 3/2 = 1 1/2. In Zeile 3 stehen Zähler und Nenner vertauscht.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6863}, {"l": "sach", "t": "sach", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In einer Klasse sind 36 Kinder. 5/6 der Kinder fahren mit dem Rad. Von diesen Radfahrern tragen 2/5 einen Helm. Die Radfahrer sind ① Kinder. Davon tragen ② einen Helm. Das ist der Bruchteil ③/④ der ganzen Klasse (vollständig gekürzt).", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [30, 12, 1, 3]}, "h": "Der zweite Bruch gehört zu den Radfahrern, nicht zur ganzen Klasse.", "w": "5/6 von 36 sind 30 Radfahrer. 2/5 von 30 sind 12 Kinder mit Helm. 12 von 36 sind 12/36 = 1/3 der ganzen Klasse.", "form": "lueckenweg", "zaehlt": "nein", "r": 6864}, {"l": "sach", "t": "sach", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Svens Taschengeld im Monat beträgt 12,50 €. Er gibt 3/5 davon aus. Von dem, was übrig bleibt, spart er 3/4. Wie viel Euro spart er?"}, "o": {"wert": 3.75, "einheit": "€"}, "h": "Wie viel Euro bleiben nach den 3/5? Der zweite Bruch gehört zu diesem Rest.", "w": "3/5 von 12,50 € sind 7,50 €. Übrig: 12,50 € − 7,50 € = 5 €. 3/4 von 5 € sind 3,75 €.", "form": "anwenden", "zaehlt": "ja", "r": 6865}, {"l": "sach", "t": "sach", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "In einem Lager werden zuerst 2/5 der Äpfel verkauft. Von den übrigen Äpfeln werden 1/3 zu Saft verarbeitet. Es bleiben 24 kg Äpfel. Wie viele Kilogramm Äpfel waren es am Anfang?"}, "o": {"wert": 60, "einheit": "kg"}, "h": "Welcher Bruchteil der ganzen Menge bleibt am Ende übrig?", "w": "Nach dem Verkauf bleiben 3/5. Davon wird 1/3 verarbeitet, es bleiben 2/3 von 3/5 = 2/5 der Menge. 2/5 sind 24 kg, also 1/5 = 12 kg und alles 60 kg.", "form": "umkehren", "zaehlt": "ja", "r": 6866}]$auf$::jsonb),
    (52, 'messen.koerper_berechnung', 552, 15, $auf$[{"l": "quader", "t": "quader", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Quader ist 15 cm lang, 5 cm breit und 6 cm hoch. Er hat ① Kanten, und zwar je ② gleich lange Kanten in drei Sorten (Länge, Breite, Höhe). Alle Kanten zusammen sind ③ cm lang. Die längsten Kanten zusammen sind ④ cm lang.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [12, 4, 104, 60]}, "h": "Wie viele Kanten laufen in jede Richtung (Länge, Breite, Höhe)?", "w": "Ein Quader hat 12 Kanten, je 4 in den drei Richtungen. Alle Kanten zusammen: 4 · (15 + 5 + 6) = 4 · 26 = 104 cm. Die vier längsten Kanten sind zusammen 4 · 15 = 60 cm lang.", "form": "lueckenweg", "zaehlt": "nein", "r": 6553}, {"l": "quader", "t": "quader", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Das Netz eines Quaders besteht aus sechs Rechtecken: zwei Rechtecke mit 6 cm mal 4 cm, zwei mit 6 cm mal 3 cm und zwei mit 4 cm mal 3 cm. Wie groß ist das Volumen des Quaders in cm³?"}, "o": {"wert": 72, "einheit": "cm³"}, "h": "Aus den Rechtecken kannst du die drei Kantenlängen des Quaders ablesen.", "w": "Die Kanten sind 6 cm, 4 cm und 3 cm lang. V = 6 · 4 · 3 = 72 cm³.", "form": "bruecke", "zaehlt": "ja", "r": 6554}, {"l": "quader", "t": "quader", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Quader hat eine quadratische Grundfläche mit der Seitenlänge 5 cm. Alle zwölf Kanten zusammen sind 76 cm lang. Wie hoch ist der Quader in Zentimetern?"}, "o": {"wert": 9, "einheit": "cm"}, "h": "Wie viele Kanten sind 5 cm lang? Wie viele sind Höhenkanten?", "w": "Acht Kanten (vier unten, vier oben) sind je 5 cm lang: 8 · 5 = 40 cm. Für die vier Höhenkanten bleiben 76 − 40 = 36 cm, eine ist 36 : 4 = 9 cm hoch. Probe: 40 + 4 · 9 = 76.", "form": "umkehren", "zaehlt": "ja", "r": 6555}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Quader ist 10 cm lang, 6 cm breit und 4 cm hoch. Boden und Deckel zusammen haben ① cm². Vorder- und Rückseite zusammen haben ② cm². Die beiden Seitenflächen zusammen haben ③ cm². Die Oberfläche ist ④ cm². Ein Würfel mit 6 cm Kante hat 216 cm² Oberfläche. Der Quader hat ⑤ cm² mehr.", "schablone": "① = □; ② = □; ③ = □; ④ = □; ⑤ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [120, 80, 48, 248, 32]}, "h": "Jede Fläche kommt zweimal vor.", "w": "Boden und Deckel: 2 · 10 · 6 = 120 cm². Vorn und hinten: 2 · 10 · 4 = 80 cm². Seiten: 2 · 6 · 4 = 48 cm². Zusammen 248 cm². Gegenüber dem Würfel: 248 cm² − 216 cm² = 32 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 6556}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein offener Karton (ohne Deckel) ist 40 cm lang, 30 cm breit und 20 cm hoch. Ein Quadratmeter Pappe kostet 6 €. Wie viel Euro kostet die Pappe für einen Karton?"}, "o": {"wert": 2.4, "einheit": "€"}, "h": "Rechne die Fläche zuerst in Quadratzentimetern und dann in Quadratmetern. 1 m² = 10 000 cm².", "w": "Boden: 40 · 30 = 1200 cm². Vier Wände: 2 · 40 · 20 + 2 · 30 · 20 = 2800 cm². Zusammen 4000 cm² = 0,4 m². 0,4 · 6 € = 2,40 €.", "form": "anwenden", "zaehlt": "ja", "r": 6557}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Würfel hat die Oberfläche 150 cm². Wie lang ist eine Kante in Zentimetern?"}, "o": {"wert": 5, "einheit": "cm"}, "h": "Wie groß ist eine einzelne Seitenfläche? Welche Zahl mal sich selbst ergibt diese Fläche?", "w": "Ein Würfel hat 6 gleiche Flächen. 150 : 6 = 25 cm². Eine Fläche ist a · a = 25, also a = 5 cm. Probe: 6 · 25 = 150.", "form": "umkehren", "zaehlt": "ja", "r": 6558}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Zimmer ist 5 m lang, 4 m breit und 2,5 m hoch. Die vier Wände und die Decke werden gestrichen, der Boden nicht. Die vier Wände haben zusammen ① m². Die Decke hat ② m². Zusammen sind das ③ m². Ein Liter Farbe reicht für 5 m². Man braucht ④ Liter.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [45, 20, 65, 13]}, "h": "Die Wände bilden zusammen einen Streifen: Umfang des Bodens mal Höhe.", "w": "Wände: Umfang 2 · (5 + 4) = 18 m, mal 2,5 m = 45 m². Decke: 5 · 4 = 20 m². Zusammen 65 m². Farbe: 65 : 5 = 13 Liter.", "form": "lueckenweg", "zaehlt": "nein", "r": 6559}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Schachtel ist 20 cm lang, 10 cm breit und 5 cm hoch. Weg A: Berechne die sechs Seitenflächen einzeln. Weg B: Berechne den Mantel (Umfang des Bodens mal Höhe) und addiere Boden und Deckel. Wie viel Quadratzentimeter Pappe braucht man für die ganze Schachtel?"}, "o": {"wert": 700, "einheit": "cm²"}, "h": "Beide Wege müssen dieselbe Fläche ergeben.", "w": "Weg A: 2 · (200 + 100 + 50) = 700 cm². Weg B: Mantel: 2 · (20 + 10) · 5 = 300 cm². Boden und Deckel: 2 · 200 = 400 cm². 300 + 400 = 700 cm².", "form": "zwei_wege", "zaehlt": "ja", "r": 6560}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Aquarium ohne Deckel ist 100 cm lang, 40 cm breit und 50 cm hoch. Es wird aus Glas gebaut. Ein Quadratmeter Glas kostet 6 €. Wie viel Euro kostet das Glas?"}, "o": {"wert": 10.8, "einheit": "€"}, "h": "Welche Flächen aus Glas gibt es? Der Deckel gehört nicht dazu.", "w": "Boden: 100 · 40 = 4000 cm². Vorder- und Rückwand: 2 · 100 · 50 = 10 000 cm². Seitenwände: 2 · 40 · 50 = 4000 cm². Zusammen 18 000 cm² = 1,8 m². 1,8 · 6 € = 10,80 €.", "form": "anwenden", "zaehlt": "ja", "r": 6561}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Zwei Würfel mit je 4 cm Kante werden mit je einer Fläche aneinandergeklebt. Ein einzelner Würfel hat ① cm² Oberfläche. Beide einzeln zusammen haben ② cm². Die aufeinanderliegenden Flächen sind zusammen ③ cm² groß. Die Oberfläche des neuen Körpers ist ④ cm².", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [96, 192, 32, 160]}, "h": "Die verklebten Flächen liegen innen und gehören nicht mehr zur Oberfläche.", "w": "Ein Würfel: 6 · 4 · 4 = 96 cm². Beide: 192 cm². Zwei verklebte Flächen: 2 · 16 = 32 cm². 192 − 32 = 160 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 6562}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Fünf Würfel mit je 2 cm Kante liegen so zusammengeklebt: Vier Würfel bilden eine gerade Reihe, ein fünfter Würfel ist an der Seite des ersten Würfels der Reihe angeklebt. Alles liegt auf einer Ebene. Weg A: Zähle alle Würfelflächen (5 · 6) und ziehe die verdeckten Flächen ab (jede Klebestelle verdeckt 2 Flächen). Weg B: Zähle die sichtbaren Flächen von oben, unten, vorn, hinten, links und rechts. Wie groß ist die Oberfläche in cm²?"}, "o": {"wert": 88, "einheit": "cm²"}, "h": "Eine Würfelfläche hat 2 · 2 = 4 cm². Beide Wege müssen dieselbe Zahl an Flächen ergeben.", "w": "Weg A: 30 Flächen. Es gibt 4 Klebestellen, die 8 Flächen verdecken. 22 Flächen. Weg B: oben 5, unten 5, vorn 4, hinten 4, links 2, rechts 2: ebenfalls 22 Flächen. 22 · 4 cm² = 88 cm².", "form": "zwei_wege", "zaehlt": "ja", "r": 6563}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Zwei gleiche Würfel werden mit je einer Fläche aufeinandergeklebt. Der entstandene Quader hat die Oberfläche 160 cm². Wie lang ist die Kante eines Würfels in Zentimetern?"}, "o": {"wert": 4, "einheit": "cm"}, "h": "Aus wie vielen Würfelflächen besteht die Oberfläche des Quaders?", "w": "Zwei Würfel haben 12 Flächen, zwei davon sind verdeckt: 10 Flächen bleiben. 160 : 10 = 16 cm² je Fläche. Eine Fläche ist a · a = 16, also a = 4 cm.", "form": "umkehren", "zaehlt": "ja", "r": 6564}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Würfel hat die Kantenlänge 5 cm. Seine Oberfläche ist ① cm². Wird jede Kante verdoppelt, ist die neue Kante ② cm lang. Die neue Oberfläche ist dann ③ cm². Die neue Oberfläche ist ④-mal so groß wie die alte.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [150, 10, 600, 4]}, "h": "Ein Würfel hat sechs gleiche Flächen.", "w": "Oberfläche: 6 · 5 · 5 = 150 cm². Neue Kante: 10 cm. Neue Oberfläche: 6 · 10 · 10 = 600 cm². Das ist 600 : 150 = 4-mal so viel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6565}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Maße sind in cm angegeben. Welche Aussage passt zur Rechnung 2 · (5 · 4 + 5 · 3 + 4 · 3) = 94?"}, "a": ["Volumen eines Quaders mit den Kanten 5 cm, 4 cm und 3 cm: 94 cm³", "Summe aller Kanten eines Quaders mit 5 cm, 4 cm und 3 cm: 94 cm", "Oberfläche eines Würfels mit der Kante 5 cm: 94 cm²", "Oberfläche eines Quaders mit den Kanten 5 cm, 4 cm und 3 cm: 94 cm²"], "o": {"index": 3}, "h": "Wie viele Flächen hat ein Quader, und wie viele davon sind gleich groß?", "w": "In der Klammer stehen die drei verschiedenen Flächen 5 · 4, 5 · 3 und 4 · 3. Jede kommt zweimal vor, deshalb der Faktor 2. Das ist die Oberfläche: 2 · 47 = 94 cm².", "form": "bruecke", "zaehlt": "ja", "r": 6566}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Mara behauptet: „Haben zwei Quader dasselbe Volumen, dann haben sie auch dieselbe Oberfläche.“ Sie vergleicht Quader A (4 cm · 3 cm · 2 cm) und Quader B (6 cm · 4 cm · 1 cm). Zeile 1: Volumen A: 4 · 3 · 2 = 24 cm³; Volumen B: 6 · 4 · 1 = 24 cm³ Zeile 2: Oberfläche A: 2 · (12 + 8 + 6) = 52 cm² Zeile 3: Oberfläche B: 2 · (24 + 6 + 4) = 68 cm² Zeile 4: Also haben beide Quader dieselbe Oberfläche. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Vergleiche die Oberflächen in Zeile 2 und 3.", "w": "Die Volumen sind gleich (24 cm³), aber die Oberflächen sind 52 cm² und 68 cm². Zeile 4 widerspricht den Zeilen 2 und 3. Die Behauptung ist falsch.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6567}]$auf$::jsonb),
    (59, 'terme.aufstellen', 534, 18, $auf$[{"l": "struktur", "t": "struktur", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Termarten sind der Reihe nach nummeriert, beginnend bei 1: Summe, Differenz, Produkt, Quotient. Welche Nummer hat die Termart von (3 + a) · 4 − 6? ①. Für a = 5 hat die Klammer den Wert ②. Der erste Operand der letzten Rechnung hat den Wert ③. Der ganze Term hat den Wert ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [2, 8, 32, 26]}, "h": "Welche Rechnung wird zuletzt ausgeführt?", "w": "Zuletzt wird 6 abgezogen: Der Term ist eine Differenz, also Nummer 2. Klammer: 3 + 5 = 8. Der erste Operand der letzten Rechnung: 8 · 4 = 32. Der ganze Term: 32 − 6 = 26.", "form": "lueckenweg", "zaehlt": "nein", "r": 6535}, {"l": "struktur", "t": "struktur", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du sollst die Termart von 2 · (x + 5) bestimmen. Welcher Weg führt sicher zum Ziel?"}, "a": ["Ein Zahlenbeispiel (x = 1) in der richtigen Reihenfolge durchrechnen (Klammer 6, dann mal 2) und die letzte Rechnung benennen: ein Produkt.", "Von links nach rechts rechnen: zuerst 2 · x, dann + 5. Also eine Summe.", "Die Klammer weglassen, denn Klammern ändern die Termart nicht: eine Summe aus 2 · x und 5.", "Den Term in Wörter fassen: zwei plus x plus fünf. Also eine Summe."], "o": {"index": 0}, "h": "Welche Rechenart wird zuletzt ausgeführt?", "w": "Zuerst wird x + 5 gerechnet (Klammer), zuletzt wird mit 2 malgenommen. Also ein Produkt aus 2 und der Summe x + 5. Probe mit x = 1: 2 · 6 = 12, aber 2 · 1 + 5 = 7.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 6536}, {"l": "struktur", "t": "struktur", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Tim berechnet 3 + 4 · a für a = 2. Zeile 1: Man rechnet zuerst 3 + 4 und dann mal a. Zeile 2: 3 + 4 = 7, also 7 · 2 = 14 Zeile 3: Der Wert des Terms ist 14. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Welche Rechnung kommt zuerst: Plus oder Mal?", "w": "Punktrechnung geht vor Strichrechnung: 4 · 2 = 8, dann 3 + 8 = 11. Zeile 1 beschreibt eine falsche Reihenfolge, die Folgezeilen rechnen damit richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6537}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 2a² − 3b für a = 4 und b = 5. Zuerst die Potenz a²: ①. Dann 2 mal diese Zahl: ②. Dann 3b: ③. Der Termwert ist ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [16, 32, 15, 17]}, "h": "Die Hochzahl 2 gehört nur zur 4, nicht zur 2 davor.", "w": "4² = 16. 2 · 16 = 32. 3 · 5 = 15. 32 − 15 = 17.", "form": "lueckenweg", "zaehlt": "nein", "r": 6538}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne den Wert von 4 · (a + 3) − 2a für a = 5 auf zwei Wegen. Weg A: Setze a = 5 sofort ein. Weg B: Multipliziere die Klammer aus (jedes Glied in der Klammer mal 4), fasse gleiche Buchstabenteile zusammen und setze dann a = 5 ein. Wie groß ist der Wert des Terms?"}, "o": {"wert": 22}, "h": "Beide Wege müssen denselben Wert ergeben.", "w": "Weg A: 4 · 8 − 10 = 32 − 10 = 22. Weg B: 4a + 12 − 2a = 2a + 12. Für a = 5: 10 + 12 = 22.", "form": "zwei_wege", "zaehlt": "ja", "r": 6539}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welchen Wert von a hat der Term 4a − 3 den Wert 21?"}, "o": {"wert": 6}, "h": "Kehre die Rechenschritte um, beginnend beim letzten.", "w": "4a − 3 = 21. Erst 3 addieren: 4a = 24. Dann durch 4 teilen: a = 6. Probe: 4 · 6 − 3 = 21.", "form": "umkehren", "zaehlt": "ja", "r": 6540}, {"l": "uebersetzen", "t": "uebersetzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Taxi berechnet eine feste Grundgebühr und dazu einen festen Preis je Kilometer. Eine Fahrt über 4 km kostet 11 €, eine Fahrt über 5 km kostet 13 €. Jeder Kilometer kostet ① €. Die Grundgebühr beträgt ② €. Der Preis für k Kilometer ist der Term ② + ① · k. Eine Fahrt über 12 km kostet ③ €. Hin- und Rückfahrt sind getrennte Taxifahrten über je 12 km, jede mit neuer Grundgebühr; sie kosten zusammen ④ €.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [2, 3, 27, 54]}, "h": "Was kommt von 4 km auf 5 km dazu?", "w": "Ein Kilometer mehr kostet 13 € − 11 € = 2 €. Für 4 km zahlt man 4 · 2 € = 8 €, die restlichen 3 € sind die Grundgebühr. Term: 3 + 2 · k. 12 km: 3 + 2 · 12 = 27 €. Hin und zurück: 2 · 27 € = 54 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 6541}, {"l": "uebersetzen", "t": "uebersetzen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Welcher Term passt zu dem Satz: „Das Doppelte von x, vermindert um 5“?"}, "a": ["2 · (x − 5)", "x² − 5", "2x − 5", "2 + x − 5"], "o": {"index": 2}, "h": "Was passiert zuerst mit x, was danach?", "w": "Das Doppelte von x ist 2x. Davon werden 5 abgezogen: 2x − 5. Probe mit x = 7: Doppeltes 14, minus 5 ergibt 9.", "form": "bruecke", "zaehlt": "ja", "r": 6542}, {"l": "uebersetzen", "t": "uebersetzen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Alex ist a Jahre alt. Seine Schwester ist 3 Jahre jünger als er. Sein Vater ist dreimal so alt wie Alex und noch 2 Jahre älter. Alex ist 11 Jahre alt. Wie viele Jahre sind die drei zusammen alt?"}, "o": {"wert": 54}, "h": "Schreibe für jede Person einen Term mit a auf.", "w": "Alex: a. Schwester: a − 3. Vater: 3a + 2. Zusammen: a + (a − 3) + (3a + 2) = 5a − 1. Für a = 11: 55 − 1 = 54. Probe: 11 + 8 + 35 = 54.", "form": "anwenden", "zaehlt": "ja", "r": 6543}, {"l": "sachsituation", "t": "sachsituation", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Im Kino kostet eine Kinderkarte 7 € und eine Erwachsenenkarte 9 €. Eine Familie kauft Karten für k Kinder und 2 Erwachsene. Der Preis in Euro ist der Term 7 · k + ①. Für 3 Kinder zahlt die Familie ② €. Mit einem 50-Euro-Schein bekommt sie dann ③ € zurück. Für 4 Kinder zahlt sie ④ €.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [18, 39, 11, 46]}, "h": "Der feste Teil des Preises hängt nicht von k ab.", "w": "Die Erwachsenenkarten kosten 2 · 9 € = 18 €, unabhängig von k. 3 Kinder: 7 · 3 + 18 = 39 €. Rückgeld: 50 € − 39 € = 11 €. 4 Kinder: 7 · 4 + 18 = 46 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 6544}, {"l": "sachsituation", "t": "sachsituation", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Am Schulkiosk kostet eine Brezel 0,80 € und ein Apfel 0,60 €. Ein Kind kauft b Brezeln und 2 Äpfel und bezahlt mit einem 5-Euro-Schein. Welcher Term gibt an, wie viel Euro es zurückbekommt?"}, "a": ["5 − 0,80 · b + 2 · 0,60", "5 − 0,80 · (b + 2) − 0,60", "5 − (0,80 · b + 2 · 0,60)", "(5 − 0,80) · b − 2 · 0,60"], "o": {"index": 2}, "h": "Was kosten alle Brezeln und alle Äpfel zusammen? Das Rückgeld ist der Rest vom Schein.", "w": "b Brezeln kosten 0,80 · b €, 2 Äpfel kosten 2 · 0,60 €. Zusammen 0,80 · b + 2 · 0,60. Das Rückgeld ist 5 − (0,80 · b + 2 · 0,60). Probe b = 3: 5 − (2,40 + 1,20) = 1,40 €.", "form": "anwenden", "zaehlt": "ja", "r": 6545}, {"l": "sachsituation", "t": "sachsituation", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Tarif A kostet 8 € Grundgebühr und 0,05 € je Minute. Tarif B kostet 2 € Grundgebühr und 0,15 € je Minute. Weg A: Lege eine Tabelle mit den Preisen für 10, 20, 30 … Minuten an und suche die Stelle, an der beide Preise gleich sind. Weg B: Teile den Unterschied der Grundgebühren durch den Unterschied der Minutenpreise. Nach wie vielen Minuten kosten beide Tarife gleich viel?"}, "o": {"wert": 60, "einheit": "min"}, "h": "Wie viel mehr Grundgebühr zahlt man bei A, wie viel weniger pro Minute?", "w": "Weg A: Die Tabelle zeigt bei 60 Minuten für A 8 € + 3 € = 11 € und für B 2 € + 9 € = 11 €. Weg B: 6 € Unterschied bei der Grundgebühr, pro Minute spart A 0,10 €. 6 : 0,10 = 60 Minuten.", "form": "zwei_wege", "zaehlt": "ja", "r": 6546}, {"l": "muster", "t": "muster", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Figur 1 hat 10 Plättchen, Figur 2 hat 14 und Figur 3 hat 18. Bei jeder Figur kommen ① Plättchen dazu. Die Anzahl bei Figur n ist ①n + ②. Figur 20 hat ③ Plättchen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [4, 6, 86]}, "h": "Wie viele Plättchen kommen von einer Figur zur nächsten dazu?", "w": "Von 10 zu 14 zu 18 sind es jedes Mal 4 mehr. Die Figur n hat 4n + 6 Plättchen (Figur 1: 4 + 6 = 10). Figur 20: 4 · 20 + 6 = 86.", "form": "lueckenweg", "zaehlt": "nein", "r": 6547}, {"l": "muster", "t": "muster", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Eine Wertetabelle zeigt: n = 1 ergibt 7, n = 2 ergibt 10, n = 3 ergibt 13, n = 4 ergibt 16. Welcher Term gehört zu dieser Tabelle?"}, "a": ["3n + 4", "3n + 7", "n + 6", "7n"], "o": {"index": 0}, "h": "Wie viel kommt von einer Zeile zur nächsten dazu? Setze dann n = 1 ein.", "w": "Von Zeile zu Zeile kommen 3 dazu, also 3n + etwas. Für n = 1: 3 + 4 = 7. Probe n = 4: 3 · 4 + 4 = 16.", "form": "bruecke", "zaehlt": "ja", "r": 6548}, {"l": "muster", "t": "muster", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Figur n eines Musters hat 4n + 3 Plättchen. Bei welcher Figur sind es genau 27 Plättchen?"}, "o": {"wert": 6}, "h": "Kehre die Rechnung um: Was passiert zuletzt mit 4n?", "w": "4n + 3 = 27. Erst 3 abziehen: 4n = 24. Dann durch 4 teilen: n = 6. Probe: 4 · 6 + 3 = 27.", "form": "umkehren", "zaehlt": "ja", "r": 6549}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Das Ausleihen eines Rollers kostet 4x + 15 Euro, wobei x die Zahl der Stunden ist. Für 8 Stunden zahlt man ① €. Verlängert man um 3 Stunden, zahlt man für 11 Stunden ② €. Mit einem 100-Euro-Schein bekommt man dafür ③ € zurück.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [47, 59, 41]}, "h": "Wie viel Euro kommen mit jeder weiteren Stunde dazu?", "w": "8 Stunden: 4 · 8 + 15 = 47. Jede weitere Stunde kostet 4 € mehr, 3 Stunden also 12 € mehr: 59 €. Probe: 4 · 11 + 15 = 59. Rückgeld: 100 € − 59 € = 41 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 6550}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Für das Ausleihen eines Rollers gilt: Der Preis in Euro ist 4x + 15, wobei x die Zahl der Stunden ist. Was bedeutet die Rechnung 4 · 6 + 15 = 39?"}, "a": ["Für 39 Stunden zahlt man 6 €.", "Eine Stunde kostet 39 €.", "Man zahlt 15 Stunden lang je 4 €.", "Für 6 Stunden zahlt man 39 €."], "o": {"index": 3}, "h": "Was ist x? Was ist das Ergebnis der Rechnung?", "w": "x ist die Zahl der Stunden. 4 · 6 steht für 6 Stunden zu je 4 €, die 15 € fallen einmal an. Das Ergebnis 39 ist der Preis in Euro.", "form": "bruecke", "zaehlt": "ja", "r": 6551}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Nina vereinfacht den Term 4x + 15, der den Preis für das Ausleihen eines Rollers für x Stunden beschreibt. Zeile 1: Man darf die Zahlen 4 und 15 zusammenzählen: 4x + 15 = 19x. Zeile 2: Für x = 2 ergibt 19x den Wert 38. Zeile 3: Also kostet das Ausleihen für 2 Stunden 38 €. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Setze x = 2 in den ursprünglichen Term ein und vergleiche.", "w": "4x + 15 hat für x = 2 den Wert 4 · 2 + 15 = 23. Die 15 gehört nicht zu x, man darf sie nicht mit der 4 zusammenzählen. Die Zeilen 2 und 3 rechnen mit 19x richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6552}]$auf$::jsonb),
    (93, 'messen.flaechen_vielecke', 375, 24, $auf$[{"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Parallelogramm hat die Grundseite 15 cm und die Höhe 6 cm. Seine Fläche ist ① cm². Nimmt man die schräge Seite mit 9 cm als Grundseite, gehört dazu die Höhe ② cm. Eine Diagonale teilt das Parallelogramm in gleiche Dreiecke; jedes hat ③ cm².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [90, 10, 45]}, "h": "Fläche = Grundseite mal Höhe. Die Höhe steht senkrecht auf der Grundseite.", "w": "A = 15 cm · 6 cm = 90 cm². Mit der Grundseite 9 cm: Höhe = 90 : 9 = 10 cm. Ein Dreieck hat 90 : 2 = 45 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 6376}, {"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Beet hat die Form eines Parallelogramms. Die Grundseite ist 8 m lang. Der Abstand zur gegenüberliegenden Seite beträgt 3,5 m. Ein Kilogramm Rasensamen reicht für 7 m². Wie viele Kilogramm Rasensamen braucht man?"}, "o": {"wert": 4, "einheit": "kg"}, "h": "Berechne zuerst die Fläche des Beets.", "w": "A = 8 m · 3,5 m = 28 m². 28 : 7 = 4. Man braucht 4 kg.", "form": "anwenden", "zaehlt": "ja", "r": 6377}, {"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Rechteck (12 cm lang, 9 cm breit) und ein Parallelogramm haben denselben Flächeninhalt. Die Grundseite des Parallelogramms ist 18 cm lang. Wie hoch ist das Parallelogramm in Zentimetern?"}, "o": {"wert": 6, "einheit": "cm"}, "h": "Wie groß ist die Fläche des Rechtecks?", "w": "Rechteck: 12 · 9 = 108 cm². Parallelogramm: 18 · h = 108, also h = 108 : 18 = 6 cm.", "form": "umkehren", "zaehlt": "ja", "r": 6378}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Dreieck hat die Grundseite 14 cm und die Höhe 9 cm. Das Rechteck mit denselben Maßen hat ① cm². Das Dreieck hat ② cm². Ein zweites Dreieck hat dieselbe Grundseite, ist aber 4 cm höher. Seine Fläche ist ③ cm².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [126, 63, 91]}, "h": "Ein Dreieck füllt nur einen Teil des Rechtecks mit gleicher Grundseite und Höhe.", "w": "Rechteck: 14 · 9 = 126 cm². Dreieck: 63 cm². Zweites Dreieck: 14 · 13 : 2 = 91 cm², das sind 28 cm² mehr als 63 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 6379}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Welche Figur gehört zur Rechnung 14 · 9 : 2 = 63?"}, "a": ["Ein Rechteck mit den Seiten 14 cm und 9 cm", "Ein Dreieck mit der Grundseite 14 cm und der Höhe 9 cm", "Ein Parallelogramm mit der Grundseite 14 cm und der Höhe 9 cm", "Ein Dreieck mit den Seiten 14 cm und 9 cm und einer Höhe von 2 cm"], "o": {"index": 1}, "h": "Was bedeutet das „: 2“ in der Rechnung?", "w": "Grundseite mal Höhe ist die Fläche eines Rechtecks oder Parallelogramms. Das Dreieck ist halb so groß: g · h : 2. Also gehört die Rechnung zu einem Dreieck mit g = 14 cm und h = 9 cm.", "form": "bruecke", "zaehlt": "ja", "r": 6380}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Dreieck hat einen Flächeninhalt von 36 cm² und eine Höhe von 8 cm. Wie lang ist die zugehörige Grundseite in Zentimetern?"}, "o": {"wert": 9, "einheit": "cm"}, "h": "Wie hängt der Flächeninhalt eines Dreiecks mit Grundseite und Höhe zusammen?", "w": "A = g · h : 2. Also g · 8 = 72 und g = 72 : 8 = 9 cm. Probe: 9 · 8 : 2 = 36.", "form": "umkehren", "zaehlt": "ja", "r": 6381}, {"l": "trapez", "t": "trapez", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Trapez hat die parallelen Seiten 9 cm und 5 cm und die Höhe 6 cm. Die Summe der parallelen Seiten ist ① cm. Die Fläche ist ② cm². Ein Rechteck mit derselben Fläche und der Breite 6 cm ist ③ cm lang.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [14, 42, 7]}, "h": "Fläche = (a + c) mal Höhe durch 2.", "w": "9 + 5 = 14. A = 14 · 6 : 2 = 42 cm². Rechteck: 42 : 6 = 7 cm lang. Das ist die mittlere Länge der parallelen Seiten.", "form": "lueckenweg", "zaehlt": "nein", "r": 6382}, {"l": "trapez", "t": "trapez", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein gleichschenkliges Trapez hat die parallelen Seiten 12 cm und 8 cm und die Höhe 5 cm. Weg A: Rechne mit der Trapezformel. Weg B: Zerlege das Trapez in ein Rechteck mit der kurzen Seite und zwei Dreiecke, die zusammen die Grundseite 12 − 8 = 4 cm haben. Wie groß ist die Fläche in cm²?"}, "o": {"wert": 50, "einheit": "cm²"}, "h": "Beide Wege müssen dieselbe Fläche ergeben.", "w": "Weg A: (12 + 8) · 5 : 2 = 50 cm². Weg B: Rechteck 8 · 5 = 40 cm². Die beiden Dreiecke haben zusammen die Grundseite 4 cm und die Höhe 5 cm: 4 · 5 : 2 = 10 cm². 40 + 10 = 50 cm².", "form": "zwei_wege", "zaehlt": "ja", "r": 6383}, {"l": "trapez", "t": "trapez", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Garten hat die Form eines Trapezes. Die parallelen Seiten sind 30 m (zur Straße) und 22 m lang. Der Abstand zwischen ihnen beträgt 15 m. Rollrasen kostet 3,20 € je Quadratmeter. Wie viel Euro kostet der Rasen für den ganzen Garten?"}, "o": {"wert": 1248, "einheit": "€"}, "h": "Berechne zuerst die Fläche des Gartens.", "w": "A = (30 + 22) · 15 : 2 = 390 m². 390 · 3,20 € = 1248 €.", "form": "anwenden", "zaehlt": "ja", "r": 6384}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Trapez hat die Fläche 84 cm². Die parallelen Seiten sind 10 cm und 14 cm lang. Die Summe der parallelen Seiten ist ① cm. Zweimal die Fläche ist ② cm². Die Höhe ist ③ cm. Das sind ④ Millimeter.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [24, 168, 7, 70]}, "h": "Stelle die Formel A = (a + c) · h : 2 nach h um.", "w": "Aus 84 = 24 · h : 2 folgt 168 = 24 · h. Also h = 168 : 24 = 7 cm = 70 mm.", "form": "lueckenweg", "zaehlt": "nein", "r": 6385}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Parallelogramm und ein Dreieck haben beide den Flächeninhalt 60 cm² und beide die Höhe 6 cm. Um wie viele Zentimeter ist die Grundseite des Dreiecks länger als die des Parallelogramms?"}, "o": {"wert": 10, "einheit": "cm"}, "h": "Berechne beide Grundseiten mit den umgestellten Formeln.", "w": "Parallelogramm: g = 60 : 6 = 10 cm. Dreieck: g = 2 · 60 : 6 = 20 cm. Unterschied: 20 cm − 10 cm = 10 cm.", "form": "umkehren", "zaehlt": "ja", "r": 6386}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Mira bestimmt die Höhe eines Dreiecks mit dem Flächeninhalt 45 cm² und der Grundseite 15 cm. Zeile 1: Dreieck: A = g · h : 2 Zeile 2: 45 = 15 · h : 2 Zeile 3: 45 · 2 = 90, also 15 · h = 90 Zeile 4: h = 90 · 15 = 1350 In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Wie rechnet man, wenn eine Zahl mit g malgenommen wurde?", "w": "Aus 15 · h = 90 folgt h = 90 : 15 = 6 cm. In Zeile 4 wurde malgenommen statt geteilt.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6387}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Haus hat vorn die Form eines Fünfecks: ein Rechteck (10 m breit, 6 m hoch) und darüber ein Dreieck als Giebel (Grundseite 10 m, Höhe 4 m). Das Rechteck hat ① m². Der Giebel hat ② m². Zusammen sind es ③ m². Der Giebel ist um ④ m² kleiner als das Rechteck.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [60, 20, 80, 40]}, "h": "Zerlege die Figur in ein Rechteck und ein Dreieck.", "w": "Rechteck: 10 · 6 = 60 m². Dreieck: 10 · 4 : 2 = 20 m². Zusammen 80 m². Unterschied: 60 m² − 20 m² = 40 m².", "form": "lueckenweg", "zaehlt": "nein", "r": 6388}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein L-förmiges Grundstück entsteht aus einem Rechteck (20 m lang, 12 m breit), aus dem an einer Ecke ein Rechteck (8 m lang, 5 m breit) herausgeschnitten ist. Weg A: Rechne großes Rechteck minus herausgeschnittenes Rechteck. Weg B: Zerlege das Grundstück in zwei Rechtecke. Wie groß ist das Grundstück in m²?"}, "o": {"wert": 200, "einheit": "m²"}, "h": "Beide Wege müssen dieselbe Fläche ergeben.", "w": "Weg A: 240 m² − 40 m² = 200 m². Weg B: ein Teil ist (20 − 8) · 12 = 144 m², der andere 8 · (12 − 5) = 56 m². 144 + 56 = 200 m².", "form": "zwei_wege", "zaehlt": "ja", "r": 6389}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Flur ist L-förmig. Er entsteht aus einem Rechteck von 9 m mal 6 m, aus dem an einer Ecke ein Rechteck von 4 m mal 3 m herausgeschnitten ist. Der Boden wird gefliest. Ein Quadratmeter Fliesen kostet 18 €. Wie viel Euro kosten die Fliesen?"}, "o": {"wert": 756, "einheit": "€"}, "h": "Berechne zuerst die Fläche des Flurs.", "w": "Fläche: 9 · 6 − 4 · 3 = 54 − 12 = 42 m². 42 · 18 € = 756 €.", "form": "anwenden", "zaehlt": "ja", "r": 6390}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein gerades dreiseitiges Prisma ist 20 cm lang. Seine Grundfläche ist ein rechtwinkliges Dreieck mit den Seiten 9 cm, 12 cm und 15 cm. Die beiden Dreiecke haben zusammen ① cm². Die drei Rechtecke (Mantel) haben zusammen ② cm². Die Oberfläche ist ③ cm². Der Mantel ist um ④ cm² größer als die beiden Dreiecke zusammen.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [108, 720, 828, 612]}, "h": "Wickelt man den Mantel ab, entsteht ein Rechteck. Welche Seiten hat es?", "w": "Dreiecke: 2 · (9 · 12 : 2) = 108 cm². Mantel: (9 + 12 + 15) · 20 = 720 cm². Oberfläche: 108 + 720 = 828 cm². Unterschied: 720 cm² − 108 cm² = 612 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 6391}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Festzelt hat die Form eines liegenden Dreiecksprismas. Vorn und hinten sind gleichschenklige Dreiecke mit der Grundseite 6 m, der Höhe 4 m und den Schenkeln von je 5 m. Das Zelt ist 8 m lang. Wie viel Quadratmeter Stoff braucht man für die beiden Giebel und die beiden Dachflächen (ohne Boden)?"}, "o": {"wert": 104, "einheit": "m²"}, "h": "Die Dachflächen sind Rechtecke: Schenkellänge mal Zeltlänge.", "w": "Giebel: 2 · (6 · 4 : 2) = 24 m². Dachflächen: 2 · (5 · 8) = 80 m². Zusammen 104 m².", "form": "anwenden", "zaehlt": "ja", "r": 6392}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein gerades Prisma hat als Grundfläche ein rechtwinkliges Dreieck mit den Seiten 5 cm, 12 cm und 13 cm. Die Oberfläche des Prismas beträgt 480 cm². Wie lang ist das Prisma in Zentimetern?"}, "o": {"wert": 14, "einheit": "cm"}, "h": "Aus welchen Teilen besteht die Oberfläche des Prismas? Welcher Teil ist schon bekannt?", "w": "Dreiecke: 2 · (5 · 12 : 2) = 60 cm². Mantel: 480 − 60 = 420 cm². Der Umfang ist 30 cm, also Länge = 420 : 30 = 14 cm.", "form": "umkehren", "zaehlt": "ja", "r": 6393}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Parallelogramm hat die Grundseite 16 cm und die Höhe 5 cm; der Fußpunkt der Höhe liegt auf der Grundseite. Man schneidet an einer Seite ein Dreieck ab und setzt es auf der anderen Seite an. So entsteht ein Rechteck mit ① cm². Ein Dreieck mit derselben Grundseite und derselben Höhe hat ② cm². Ein Rechteck mit derselben Fläche wie das Parallelogramm und der Breite 8 cm ist ③ cm lang.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [80, 40, 10]}, "h": "Beim Umlegen bleibt die Fläche gleich.", "w": "Das Rechteck hat 16 · 5 = 80 cm², genau wie das Parallelogramm. Ein Dreieck mit g = 16 cm und h = 5 cm hat 40 cm². Das Rechteck mit der Breite 8 cm ist 80 : 8 = 10 cm lang.", "form": "lueckenweg", "zaehlt": "nein", "r": 6394}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Trapez hat die Fläche 56 cm², die Höhe 7 cm und eine parallele Seite von 5 cm. Wie lang ist die andere parallele Seite in Zentimetern?"}, "o": {"wert": 11, "einheit": "cm"}, "h": "Die Summe der beiden parallelen Seiten ergibt sich aus 2 · A : h.", "w": "(a + 5) · 7 : 2 = 56. Also (a + 5) · 7 = 112 und a + 5 = 16. Damit ist a = 11 cm.", "form": "umkehren", "zaehlt": "ja", "r": 6395}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ben behauptet: „Wenn man bei einem Dreieck Grundseite und Höhe verdoppelt, verdoppelt sich die Fläche.“ Er prüft es mit g = 4 cm und h = 3 cm. Zeile 1: Vorher: 4 · 3 : 2 = 6 cm² Zeile 2: Nachher mit g = 8 cm und h = 6 cm: 8 · 6 : 2 = 24 cm² Zeile 3: 24 : 6 = 4 Zeile 4: Die Fläche hat sich also verdoppelt. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Wie oft passt 6 in 24? Wie oft sind die Maße größer geworden?", "w": "Die Fläche ist 4-mal so groß: g wird 2-mal so groß und h auch, also 2 · 2 = 4. Zeile 4 zieht aus 24 : 6 = 4 den falschen Schluss.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6396}, {"l": "drachen_raute", "t": "drachen_raute", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Raute hat die Diagonalen e = 16 cm und f = 12 cm. Das Rechteck, dessen Seiten parallel zu den Diagonalen liegen und das durch die vier Eckpunkte der Raute geht, hat ① cm². Die Raute hat ② cm². Wird jede Diagonale halbiert, hat die kleinere Raute ③ cm².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [192, 96, 24]}, "h": "Die Raute füllt genau die Hälfte des umschließenden Rechtecks.", "w": "Rechteck: 16 · 12 = 192 cm². Raute: 192 : 2 = 96 cm². Formel: A = e · f : 2. Halbe Diagonalen: 8 · 6 : 2 = 24 cm², das ist ein Viertel von 96 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 6397}, {"l": "drachen_raute", "t": "drachen_raute", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Eine Raute liegt so in einem Rechteck (14 cm lang, 8 cm breit), dass ihre Ecken genau in den Mitten der Rechteckseiten liegen. Wie groß ist die Fläche der Raute in cm²?"}, "o": {"wert": 56, "einheit": "cm²"}, "h": "Wo liegen die beiden Diagonalen der Raute im Rechteck?", "w": "Die Diagonalen der Raute sind 14 cm und 8 cm lang. A = e · f : 2 = 14 · 8 : 2 = 56 cm². Das ist die Hälfte der Rechteckfläche 112 cm².", "form": "bruecke", "zaehlt": "ja", "r": 6398}, {"l": "drachen_raute", "t": "drachen_raute", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Raute hat die Diagonalen 10 cm und 24 cm. Weg A: Rechne mit der Formel e · f : 2. Weg B: Die Diagonalen teilen die Raute in vier gleiche rechtwinklige Dreiecke mit den Katheten 5 cm und 12 cm. Rechne ein Dreieck aus und nimm es mal 4. Wie groß ist die Raute in cm²?"}, "o": {"wert": 120, "einheit": "cm²"}, "h": "Beide Wege müssen dieselbe Fläche ergeben.", "w": "Weg A: 10 · 24 : 2 = 120 cm². Weg B: Ein Dreieck hat 5 · 12 : 2 = 30 cm². Vier Dreiecke: 4 · 30 = 120 cm².", "form": "zwei_wege", "zaehlt": "ja", "r": 6399}]$auf$::jsonb),
    (95, 'messen.volumen', 369, 21, $auf$[{"l": "einheitswuerfel", "t": "einheitswuerfel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Quader ist aus Einheitswürfeln mit 1 cm Kante gebaut: 6 Würfel in der Länge, 4 in der Breite und 5 Schichten übereinander. Eine Schicht hat ① Würfel. Der ganze Quader hat ② Würfel. Nimmt man die oberste Schicht weg, bleiben ③ Würfel.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [24, 120, 96]}, "h": "Zähle zuerst, wie viele Würfel in einer Schicht liegen.", "w": "Eine Schicht: 6 · 4 = 24 Würfel. Fünf Schichten: 5 · 24 = 120 Würfel. Ohne die oberste Schicht: 120 − 24 = 96 Würfel.", "form": "lueckenweg", "zaehlt": "nein", "r": 6370}, {"l": "einheitswuerfel", "t": "einheitswuerfel", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Kiste ist innen 40 cm lang, 30 cm breit und 20 cm hoch. Sie wird mit Würfeln gefüllt, die 10 cm Kantenlänge haben. Wie viele Würfel passen hinein?"}, "o": {"wert": 24}, "h": "Wie viele Würfel passen in die Länge, in die Breite und in die Höhe?", "w": "In die Länge passen 4 Würfel, in die Breite 3 und in die Höhe 2. 4 · 3 · 2 = 24 Würfel.", "form": "anwenden", "zaehlt": "ja", "r": 6371}, {"l": "einheitswuerfel", "t": "einheitswuerfel", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Quader ist 12 cm lang, 8 cm breit und 6 cm hoch. Er soll mit Würfeln der Kantenlänge 2 cm gefüllt werden. Weg A: Teile das Volumen des Quaders durch das Volumen eines kleinen Würfels. Weg B: Zähle, wie viele kleine Würfel an jeder Kante liegen, und multipliziere. Wie viele kleine Würfel sind es?"}, "o": {"wert": 72}, "h": "Beide Wege müssen dieselbe Anzahl ergeben. Ein kleiner Würfel hat 2 · 2 · 2 cm³.", "w": "Weg A: Quader 12 · 8 · 6 = 576 cm³. Ein Würfel 8 cm³. 576 : 8 = 72. Weg B: 6 · 4 · 3 = 72.", "form": "zwei_wege", "zaehlt": "ja", "r": 6372}, {"l": "quader", "t": "quader", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Quader ist 8 cm lang, 5 cm breit und 6 cm hoch. Die Grundfläche ist ① cm². Das Volumen ist ② cm³. Wird der Quader 2 cm höher, wächst das Volumen auf ③ cm³.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [40, 240, 320]}, "h": "Volumen = Grundfläche mal Höhe.", "w": "Grundfläche: 8 · 5 = 40 cm². Volumen: 40 · 6 = 240 cm³. Zwei Zentimeter mehr Höhe bringen 40 · 2 = 80 cm³ dazu: 320 cm³.", "form": "lueckenweg", "zaehlt": "nein", "r": 6373}, {"l": "quader", "t": "quader", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Quader ist 12 cm lang, 9 cm breit und 5 cm hoch. Weg A: Rechne Länge mal Breite mal Höhe. Weg B: Teile den Quader waagerecht in einen Quader von 2 cm Höhe und einen von 3 cm Höhe und addiere die beiden Volumen. Wie groß ist das Volumen in cm³?"}, "o": {"wert": 540, "einheit": "cm³"}, "h": "Beide Wege müssen dasselbe Volumen ergeben.", "w": "Weg A: 12 · 9 · 5 = 540 cm³. Weg B: 12 · 9 · 2 = 216 cm³ und 12 · 9 · 3 = 324 cm³. 216 + 324 = 540 cm³.", "form": "zwei_wege", "zaehlt": "ja", "r": 6374}, {"l": "quader", "t": "quader", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Quader hat das Volumen 504 cm³, ist 9 cm lang und 7 cm hoch. Wie breit ist er in Zentimetern?"}, "o": {"wert": 8, "einheit": "cm"}, "h": "Wie groß ist das Produkt aus Länge und Höhe?", "w": "V = l · b · h. 504 = 9 · b · 7 = 63 · b. Also b = 504 : 63 = 8 cm.", "form": "umkehren", "zaehlt": "ja", "r": 6375}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Rechne 2,4 m³ in kleinere Einheiten um. Ein Kubikmeter sind ① dm³. 2,4 m³ sind ② dm³. Das sind ③ cm³.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [1000, 2400, 2400000]}, "h": "Ein Kubikmeter ist ein Würfel mit 10 dm Kante.", "w": "1 m³ = 10 · 10 · 10 dm³ = 1000 dm³. 2,4 · 1000 = 2400 dm³. 1 dm³ = 1000 cm³, also 2 400 000 cm³.", "form": "lueckenweg", "zaehlt": "nein", "r": 6376}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Welche Angabe ist genauso groß wie 3 400 cm³?"}, "a": ["34 dm³", "3,4 dm³", "0,34 dm³", "3,4 m³"], "o": {"index": 1}, "h": "Wie viele cm³ hat ein dm³?", "w": "1 dm³ = 1 000 cm³. Die Maßzahl in dm³ ist 3 400 : 1 000 = 3,4. Also sind 3 400 cm³ = 3,4 dm³.", "form": "bruecke", "zaehlt": "ja", "r": 6377}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Schwimmbecken enthält 45 m³ Wasser. Mit einem Eimer, der 12 Liter fasst, soll es leer geschöpft werden. Es gilt 1 m³ = 1000 Liter. Wie oft muss man den Eimer füllen?"}, "o": {"wert": 3750}, "h": "In welcher Einheit ist die Wassermenge angegeben, in welcher fasst der Eimer?", "w": "45 m³ = 45 000 Liter. 45 000 : 12 = 3750. Man muss den Eimer 3750-mal füllen.", "form": "anwenden", "zaehlt": "ja", "r": 6378}, {"l": "liter", "t": "liter", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Aquarium ist innen 60 cm lang, 30 cm breit und 40 cm hoch. Sein Volumen ist ① cm³. Das sind ② Liter. Steht das Wasser 5 cm unter dem Rand, sind ③ Liter darin.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [72000, 72, 63]}, "h": "Ein Liter ist 1 dm³ = 1000 cm³.", "w": "V = 60 · 30 · 40 = 72 000 cm³ = 72 Liter. Die 5 cm unter dem Rand sind 60 · 30 · 5 = 9000 cm³ = 9 Liter. 72 − 9 = 63 Liter.", "form": "lueckenweg", "zaehlt": "nein", "r": 6379}, {"l": "liter", "t": "liter", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "In ein quaderförmiges Becken (50 cm lang, 30 cm breit) wird Wasser eingefüllt. Der Wasserspiegel steigt dabei um 4 cm. Wie viele Liter Wasser wurden eingefüllt?"}, "o": {"wert": 6, "einheit": "l"}, "h": "Das eingefüllte Wasser bildet einen flachen Quader.", "w": "Der flache Quader hat 50 · 30 · 4 = 6000 cm³. 1000 cm³ sind 1 Liter. Also wurden 6 Liter eingefüllt.", "form": "bruecke", "zaehlt": "ja", "r": 6380}, {"l": "liter", "t": "liter", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein quaderförmiger Tank hat eine Grundfläche von 2 m mal 1,5 m und fasst 4 800 Liter. Wie hoch ist der Tank in Metern?"}, "o": {"wert": 1.6, "einheit": "m"}, "h": "Passen die Einheiten von Grundfläche und Inhalt zusammen?", "w": "4 800 Liter = 4,8 m³. Grundfläche: 2 · 1,5 = 3 m². Höhe = 4,8 : 3 = 1,6 m.", "form": "umkehren", "zaehlt": "ja", "r": 6381}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Quader hat das Volumen 360 cm³. Er ist 9 cm lang und 5 cm breit. Die Grundfläche ist ① cm². Die Höhe ist ② cm. Füllt man 180 cm³ Wasser in den Quader, steht das Wasser ③ cm hoch.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [45, 8, 4]}, "h": "Aus Volumen = Grundfläche · Höhe folgt: Höhe = Volumen : Grundfläche.", "w": "Grundfläche: 9 · 5 = 45 cm². Höhe: 360 : 45 = 8 cm. Füllhöhe: 180 : 45 = 4 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 6382}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Quader hat die Grundfläche 24 cm². Sein Volumen ist genauso groß wie das eines Würfels mit der Kantenlänge 6 cm. Wie hoch ist der Quader in Zentimetern?"}, "o": {"wert": 9, "einheit": "cm"}, "h": "Berechne zuerst das Volumen des Würfels.", "w": "Würfel: 6 · 6 · 6 = 216 cm³. Quader: 24 · h = 216, also h = 216 : 24 = 9 cm.", "form": "umkehren", "zaehlt": "ja", "r": 6383}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Lara bestimmt die Breite eines Quaders mit dem Volumen 420 cm³, der Länge 7 cm und der Höhe 5 cm. Zeile 1: V = l · b · h, also 420 = 7 · b · 5 Zeile 2: 7 · 5 = 35, also 420 = 35 · b Zeile 3: b = 420 : 35 = 12 Zeile 4: Probe: 7 · 12 = 84 und 84 · 5 = 410 In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Rechne die Probe selbst nach.", "w": "84 · 5 = 420, nicht 410. Die Breite 12 cm war richtig, aber die Probe in Zeile 4 enthält einen Rechenfehler.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6384}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Körper besteht aus einem großen Quader (12 cm lang, 5 cm breit, 4 cm hoch). Obendrauf liegt ein kleiner Quader (4 cm lang, 5 cm breit, 3 cm hoch). Der große Quader hat ① cm³. Der kleine hat ② cm³. Zusammen sind es ③ cm³. Der Körper besteht aus Ton, jeder cm³ wiegt 2 g. Der Körper wiegt ④ g.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [240, 60, 300, 600]}, "h": "Rechne jeden Quader einzeln und addiere dann.", "w": "Großer Quader: 12 · 5 · 4 = 240 cm³. Kleiner Quader: 4 · 5 · 3 = 60 cm³. Zusammen: 300 cm³. Gewicht: 300 · 2 g = 600 g.", "form": "lueckenweg", "zaehlt": "nein", "r": 6385}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Aus einem Quader (8 cm lang, 6 cm breit, 5 cm hoch) wird an einer oberen Kante ein Quader von 3 cm Länge, 6 cm Breite und 2 cm Höhe herausgeschnitten. Weg A: Rechne den ganzen Quader minus den herausgeschnittenen Teil. Weg B: Zerlege den Rest in zwei Quader und addiere. Wie groß ist das Volumen des Restkörpers in cm³?"}, "o": {"wert": 204, "einheit": "cm³"}, "h": "Beide Wege müssen dasselbe Volumen ergeben.", "w": "Weg A: 240 cm³ − 36 cm³ = 204 cm³. Weg B: unten ein Quader 8 · 6 · 3 = 144 cm³, darüber 5 · 6 · 2 = 60 cm³. 144 + 60 = 204 cm³.", "form": "zwei_wege", "zaehlt": "ja", "r": 6386}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Betonsockel besteht aus zwei Quadern. Unten liegt ein Quader von 2 m Länge, 1 m Breite und 0,4 m Höhe. Darauf steht ein Quader von 1 m Länge, 1 m Breite und 0,5 m Höhe. Ein Kubikmeter Beton kostet 90 €. Wie viel Euro kostet der Beton für den Sockel?"}, "o": {"wert": 117, "einheit": "€"}, "h": "Berechne das Gesamtvolumen in Kubikmetern.", "w": "Unterer Quader: 2 · 1 · 0,4 = 0,8 m³. Oberer Quader: 1 · 1 · 0,5 = 0,5 m³. Zusammen 1,3 m³. 1,3 · 90 € = 117 €.", "form": "anwenden", "zaehlt": "ja", "r": 6387}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Würfel hat die Kantenlänge 5 cm. Sein Volumen ist ① cm³. Wird jede Kante verdoppelt, ist die neue Kantenlänge ② cm und das neue Volumen ③ cm³. Das neue Volumen ist ④-mal so groß wie das alte.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [125, 10, 1000, 8]}, "h": "Bei einem Würfel wird die Kantenlänge dreimal malgenommen.", "w": "V = 5 · 5 · 5 = 125 cm³. Neue Kante: 10 cm. Neues Volumen: 10 · 10 · 10 = 1000 cm³. Das Volumen ist 1000 : 125 = 8-mal so groß.", "form": "lueckenweg", "zaehlt": "nein", "r": 6388}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Würfel hat das Volumen 343 cm³. Schätze zuerst, ob die Kante kürzer oder länger als 10 cm ist. Wie lang ist die Kante in Zentimetern?"}, "o": {"wert": 7, "einheit": "cm"}, "h": "Schätze zuerst: Was ergibt 5 · 5 · 5, was 10 · 10 · 10? Welche Zahl liegt dazwischen?", "w": "7 · 7 · 7 = 343, die Kante ist 7 cm lang. Schätzen hilft: 5 · 5 · 5 = 125 ist zu klein, 10 · 10 · 10 = 1000 ist zu groß. Probe: 343 : 7 = 49 und 49 : 7 = 7.", "form": "umkehren", "zaehlt": "ja", "r": 6389}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Tim behauptet: „Verdoppelt man die Kantenlänge eines Würfels, verdoppelt sich das Volumen.“ Er prüft es. Zeile 1: Kante 2 cm: V = 2 · 2 · 2 = 8 cm³ Zeile 2: Kante 4 cm: V = 4 · 4 · 4 = 64 cm³ Zeile 3: 64 : 8 = 8 Zeile 4: Also hat sich das Volumen verdoppelt. In welcher Zeile steht zum ersten Mal eine falsche Aussage?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Wie oft passt 8 in 64? Ist das dasselbe wie verdoppeln?", "w": "Das Volumen ist 8-mal so groß, nicht 2-mal. Die Zeilen 1 bis 3 stimmen; Zeile 4 zieht aus 64 : 8 = 8 den falschen Schluss.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 6390}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 198 then fehler := fehler || ('zusammen ' || gesamt || ' statt 198')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (9, 10, 11, 12, 52, 59, 93, 95) group by 1 order by 1;
